1	"use client";
2	
3	import { useState, useEffect, useRef } from "react";
4	import { useRouter } from "next/navigation";
5	import { Sparkles, ChevronDown, ChevronUp, AlertTriangle, Info, ArrowRight, Copy, Check } from "lucide-react";
6	import {
7	  Card,
8	  CardHeader,
9	  CardTitle,
10	  CardContent,
11	} from "@/components/ui/card";
12	import { Button } from "@/components/ui/button";
13	import { cn } from "@/lib/utils";
14	import type {
15	  AdaExtraction,
16	  AdaFlag,
17	  AdaFieldAffected,
18	  AdaMode,
19	  AdaApiSuccess,
20	} from "@/lib/ada/types";
21	
22	// ─── Helpers ────────────────────────────────────────────────────────────────
23	
24	const LOADING_MESSAGES = [
25	  "Reading the email...",
26	  "Identifying deal terms...",
27	  "Checking for ambiguities...",
28	];
29	
30	const FLAG_CLASS_LABELS: Record<AdaFlag["flag_class"], string> = {
31	  ambiguous_net: "Ambiguous net definition",
32	  external_reference: "Terms in external document",
33	  computed_threshold: "Computed threshold",
34	  missing_overage: "Overage responsibility unspecified",
35	  unresolved_reference: "Unresolved reference",
36	  bracketed_update: "Bracketed update detected",
37	  mode_fallback: "Mode adjusted",
38	  other: "Advisory",
39	};
40	
41	function formatMoney(n: number | null | undefined): string {
42	  if (n == null) return "—";
43	  return new Intl.NumberFormat("en-US", {
44	    style: "currency",
45	    currency: "USD",
46	    minimumFractionDigits: 0,
47	    maximumFractionDigits: 0,
48	  }).format(n);
49	}
50	
51	function formatPct(n: number | null | undefined): string {
52	  if (n == null) return "—";
53	  return `${(n * 100).toFixed(0)}%`;
54	}
55	
56	// ─── Flag display ────────────────────────────────────────────────────────────
57	
58	function CopyButton({ text }: { text: string }) {
59	  const [copied, setCopied] = useState(false);
60	
61	  function handleCopy() {
62	    navigator.clipboard.writeText(text).then(() => {
63	      setCopied(true);
64	      setTimeout(() => setCopied(false), 1500);
65	    });
66	  }
67	
68	  return (
69	    <button
70	      type="button"
71	      onClick={handleCopy}
72	      className="flex items-center gap-1 text-[10.5px] text-ink-400 hover:text-ink-700 transition-colors shrink-0"
73	      aria-label="Copy question"
74	    >
75	      {copied ? (
76	        <>
77	          <Check className="h-3 w-3 text-brand-600" />
78	          <span className="text-brand-600">Copied!</span>
79	        </>
80	      ) : (
81	        <>
82	          <Copy className="h-3 w-3" />
83	          <span>Copy</span>
84	        </>
85	      )}
86	    </button>
87	  );
88	}
89	
90	function FlagItem({ flag, inline = false }: { flag: AdaFlag; inline?: boolean }) {
91	  return (
92	    <div
93	      className={cn(
94	        "rounded-md ring-1 ring-amber-200/70 bg-amber-50/60",
95	        inline ? "px-3 py-2 mt-2" : "px-4 py-3",
96	      )}
97	    >
98	      <div className="flex items-start gap-2">
99	        <AlertTriangle
100	          className={cn(
101	            "shrink-0 text-amber-600",
102	            inline ? "h-3 w-3 mt-0.5" : "h-3.5 w-3.5 mt-0.5",
103	          )}
104	        />
105	        <div className="min-w-0 w-full">
106	          <span
107	            className={cn(
108	              "font-medium text-amber-900",
109	              inline ? "text-[11px]" : "text-[12px]",
110	            )}
111	          >
112	            {FLAG_CLASS_LABELS[flag.flag_class]}
113	          </span>
114	          <p
115	            className={cn(
116	              "text-amber-800 mt-0.5 leading-relaxed",
117	              inline ? "text-[11px]" : "text-[12px]",
118	            )}
119	          >
120	            {flag.description}
121	          </p>
122	          {flag.evidence_quote && (
123	            <blockquote
124	              className={cn(
125	                "mt-1.5 pl-2 border-l-2 border-amber-300 text-amber-700 italic",
126	                inline ? "text-[10.5px]" : "text-[11px]",
127	              )}
128	            >
129	              &ldquo;{flag.evidence_quote}&rdquo;
130	            </blockquote>
131	          )}
132	          {flag.suggested_question && (
133	            <div className="mt-2 pt-2 border-t border-amber-200/60">
134	              <div className="flex items-start justify-between gap-2">
135	                <div className="min-w-0">
136	                  <div className="eyebrow text-[9px] text-amber-700 mb-1">Suggested question</div>
137	                  <p className={cn("text-amber-800 leading-relaxed", inline ? "text-[11px]" : "text-[12px]")}>
138	                    {flag.suggested_question}
139	                  </p>
140	                </div>
141	                <CopyButton text={flag.suggested_question} />
142	              </div>
143	            </div>
144	          )}
145	        </div>
146	      </div>
147	    </div>
148	  );
149	}
150	
151	// ─── Individual extraction cards ─────────────────────────────────────────────
152	
153	function FieldRow({
154	  label,
155	  value,
156	  flags,
157	}: {
158	  label: string;
159	  value: React.ReactNode;
160	  flags?: AdaFlag[];
161	}) {
162	  return (
163	    <div>
164	      <div className="eyebrow text-[10px] text-ink-500 mb-1">{label}</div>
165	      <div className="text-[13.5px] text-ink-900 font-mono tabular">{value}</div>
166	      {flags?.map((f, i) => <FlagItem key={i} flag={f} inline />)}
167	    </div>
168	  );
169	}
170	
171	function CoreTermsCard({
172	  extraction,
173	  flagMap,
174	}: {
175	  extraction: AdaExtraction;
176	  flagMap: Map<AdaFieldAffected, AdaFlag[]>;
177	}) {
178	  if (extraction.guarantee_amount == null) return null;
179	  return (
180	    <Card>
181	      <CardHeader>
182	        <CardTitle>Core terms</CardTitle>
183	      </CardHeader>
184	      <CardContent>
185	        <FieldRow
186	          label="Guarantee"
187	          value={formatMoney(extraction.guarantee_amount)}
188	          flags={flagMap.get("guarantee_amount")}
189	        />
190	      </CardContent>
191	    </Card>
192	  );
193	}
194	
195	function PercentageSplitCard({
196	  extraction,
197	  flagMap,
198	}: {
199	  extraction: AdaExtraction;
200	  flagMap: Map<AdaFieldAffected, AdaFlag[]>;
201	}) {
202	  if (extraction.percentage == null && extraction.percentage_basis == null) return null;
203	  return (
204	    <Card>
205	      <CardHeader>
206	        <CardTitle>Percentage split</CardTitle>
207	      </CardHeader>
208	      <CardContent className="space-y-4">
209	        <FieldRow
210	          label="Percentage"
211	          value={formatPct(extraction.percentage)}
212	          flags={flagMap.get("percentage")}
213	        />
214	        <FieldRow
215	          label="Basis"
216	          value={
217	            extraction.percentage_basis ? (
218	              <span className="capitalize">{extraction.percentage_basis}</span>
219	            ) : (
220	              "—"
221	            )
222	          }
223	          flags={flagMap.get("percentage_basis")}
224	        />
225	      </CardContent>
226	    </Card>
227	  );
228	}
229	
230	function CapsCard({
231	  extraction,
232	  flagMap,
233	}: {
234	  extraction: AdaExtraction;
235	  flagMap: Map<AdaFieldAffected, AdaFlag[]>;
236	}) {
237	  if (extraction.expense_cap == null && extraction.hospitality_cap == null) return null;
238	  return (
239	    <Card>
240	      <CardHeader>
241	        <CardTitle>Caps</CardTitle>
242	      </CardHeader>
243	      <CardContent className="space-y-4">
244	        {extraction.expense_cap != null && (
245	          <FieldRow
246	            label="Expense cap"
247	            value={formatMoney(extraction.expense_cap)}
248	            flags={flagMap.get("expense_cap")}
249	          />
250	        )}
251	        {extraction.hospitality_cap != null && (
252	          <FieldRow
253	            label="Hospitality cap"
254	            value={formatMoney(extraction.hospitality_cap)}
255	            flags={flagMap.get("hospitality_cap")}
256	          />
257	        )}
258	      </CardContent>
259	    </Card>
260	  );
261	}
262	
263	function EscalatorsCard({
264	  extraction,
265	  flagMap,
266	}: {
267	  extraction: AdaExtraction;
268	  flagMap: Map<AdaFieldAffected, AdaFlag[]>;
269	}) {
270	  const hasAny =
271	    extraction.ratchet != null ||
272	    extraction.walkout_pot != null ||
273	    extraction.tiered_net_split != null;
274	  if (!hasAny) return null;
275	
276	  return (
277	    <Card>
278	      <CardHeader>
279	        <CardTitle>Escalators</CardTitle>
280	      </CardHeader>
281	      <CardContent className="space-y-5">
282	        {extraction.ratchet && (
283	          <div>
284	            <div className="eyebrow text-[10px] text-ink-500 mb-2">Ratchet</div>
285	            <div className="text-[13px] text-ink-800 leading-relaxed">
286	              {formatPct(extraction.ratchet.base_percent)} base →{" "}
287	              {formatPct(extraction.ratchet.cap_percent)} above{" "}
288	              {formatPct(extraction.ratchet.trigger_capacity_pct)} capacity
289	            </div>
290	            {flagMap.get("ratchet")?.map((f, i) => <FlagItem key={i} flag={f} inline />)}
291	          </div>
292	        )}
293	        {extraction.walkout_pot && (
294	          <div>
295	            <div className="eyebrow text-[10px] text-ink-500 mb-2">Walkout pot</div>
296	            <div className="text-[13px] text-ink-800 leading-relaxed">
297	              100% of gross above {formatMoney(extraction.walkout_pot.threshold_amount)}
298	              {extraction.walkout_pot.threshold_source === "computed" && (
299	                <span className="ml-1.5 text-[11px] text-ink-400">(computed threshold)</span>
300	              )}
301	            </div>
302	            {flagMap.get("walkout_pot")?.map((f, i) => <FlagItem key={i} flag={f} inline />)}
303	          </div>
304	        )}
305	        {extraction.tiered_net_split && (
306	          <div>
307	            <div className="eyebrow text-[10px] text-ink-500 mb-2">Tiered net split</div>
308	            <div className="text-[13px] text-ink-800 leading-relaxed">
309	              {formatPct(extraction.tiered_net_split.low_percent)} up to{" "}
310	              {formatMoney(extraction.tiered_net_split.threshold_gross)} gross, then{" "}
311	              {formatPct(extraction.tiered_net_split.high_percent)}
312	            </div>
313	          </div>
314	        )}
315	      </CardContent>
316	    </Card>
317	  );
318	}
319	
320	function BonusesCard({
321	  extraction,
322	  flagMap,
323	}: {
324	  extraction: AdaExtraction;
325	  flagMap: Map<AdaFieldAffected, AdaFlag[]>;
326	}) {
327	  if (!extraction.bonuses || extraction.bonuses.length === 0) return null;
328	
329	  return (
330	    <Card>
331	      <CardHeader>
332	        <CardTitle>Bonuses</CardTitle>
333	      </CardHeader>
334	      <CardContent>
335	        <ul className="space-y-3">
336	          {extraction.bonuses.map((b, i) => (
337	            <li key={i} className="text-[13px] text-ink-800 leading-relaxed">
338	              <span className="inline-flex items-center px-1.5 py-px rounded text-[9px] font-mono uppercase tracking-wider bg-white ring-1 ring-brand-200/50 text-brand-800 mr-2">
339	                {b.type === "gross_threshold"
340	                  ? "gross"
341	                  : b.type === "attendance_threshold"
342	                    ? "attend"
343	                    : "sellout"}
344	              </span>
345	              {b.trigger}
346	              {" · "}
347	              <span className="font-mono tabular">{formatMoney(b.amount)}</span>
348	              {b.stacks && (
349	                <span className="ml-1.5 text-[11px] text-ink-400">stacks</span>
350	              )}
351	            </li>
352	          ))}
353	        </ul>
354	        {flagMap.get("bonuses")?.map((f, i) => <FlagItem key={i} flag={f} inline />)}
355	      </CardContent>
356	    </Card>
357	  );
358	}
359	
360	// ─── Delta panel (Update mode) ───────────────────────────────────────────────
361	
362	function DeltaPanel({ extraction }: { extraction: AdaExtraction }) {
363	  const changes = extraction.changes_from_previous;
364	  if (!changes || changes.length === 0) return null;
365	
366	  return (
367	    <div className="rounded-lg ring-1 ring-sky-200/70 bg-sky-50/50 px-5 py-4">
368	      <div className="eyebrow text-[10px] text-sky-700 mb-3">Changes from prior version</div>
369	      <ul className="space-y-3">
370	        {changes.map((c, i) => (
371	          <li key={i} className="text-[12.5px] text-ink-800">
372	            <div className="font-mono text-[11px] text-ink-500 mb-0.5">{c.field_path}</div>
373	            <div className="flex items-center gap-2 flex-wrap">
374	              <span className="text-ink-500 line-through">{String(c.previous_value ?? "—")}</span>
375	              <ArrowRight className="h-3 w-3 text-ink-400 shrink-0" />
376	              <span className="font-medium text-ink-900">{String(c.new_value ?? "—")}</span>
377	            </div>
378	            {c.evidence_quote && (
379	              <blockquote className="mt-1 pl-2 border-l-2 border-sky-300 text-[11px] text-sky-700 italic">
380	                &ldquo;{c.evidence_quote}&rdquo;
381	              </blockquote>
382	            )}
383	          </li>
384	        ))}
385	      </ul>
386	    </div>
387	  );
388	}
389	
390	// ─── Result display ──────────────────────────────────────────────────────────
391	
392	function ExtractionResult({
393	  extraction,
394	  flags,
395	  modeUsed,
396	  onRunAgain,
397	}: {
398	  extraction: AdaExtraction;
399	  flags: AdaFlag[];
400	  modeUsed: AdaMode;
401	  onRunAgain: () => void;
402	}) {
403	  const [showRawText, setShowRawText] = useState(false);
404	
405	  const flagMap = new Map<AdaFieldAffected, AdaFlag[]>();
406	  for (const f of flags) {
407	    const existing = flagMap.get(f.field_affected) ?? [];
408	    flagMap.set(f.field_affected, [...existing, f]);
409	  }
410	
411	  const globalFlags = flagMap.get("global") ?? [];
412	
413	  return (
414	    <div className="space-y-4">
415	      {/* Global flag banner */}
416	      {globalFlags.length > 0 && (
417	        <div className="space-y-2">
418	          {globalFlags.map((f, i) => <FlagItem key={i} flag={f} />)}
419	        </div>
420	      )}
421	
422	      {/* Delta panel — Update mode only */}
423	      {modeUsed === "update" && <DeltaPanel extraction={extraction} />}
424	
425	      {/* Extraction cards */}
426	      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
427	        <CoreTermsCard extraction={extraction} flagMap={flagMap} />
428	        <PercentageSplitCard extraction={extraction} flagMap={flagMap} />
429	        <CapsCard extraction={extraction} flagMap={flagMap} />
430	        <EscalatorsCard extraction={extraction} flagMap={flagMap} />
431	        <BonusesCard extraction={extraction} flagMap={flagMap} />
432	      </div>
433	
434	      {/* Complex structure indicator */}
435	      {extraction.complex_structure && (
436	        <div className="flex items-center gap-2 text-[12px] text-ink-500 pt-1">
437	          <Info className="h-3.5 w-3.5" />
438	          Ada marked this deal as complex — it may not fit the standard schema cleanly. Review the original text.
439	        </div>
440	      )}
441	
442	      {/* Raw text toggle */}
443	      <div className="border-t border-ink-100/80 pt-3">
444	        <button
445	          type="button"
446	          onClick={() => setShowRawText((v) => !v)}
447	          className="flex items-center gap-1.5 text-[11.5px] text-ink-400 hover:text-ink-700 transition-colors"
448	        >
449	          {showRawText ? <ChevronUp className="h-3.5 w-3.5" /> : <ChevronDown className="h-3.5 w-3.5" />}
450	          {showRawText ? "Hide" : "View"} original pasted text
451	        </button>
452	        {showRawText && (
453	          <div className="mt-2 text-[12px] text-ink-700 bg-canvas-soft rounded-lg p-4 ring-1 ring-ink-200/50 leading-relaxed whitespace-pre-wrap font-[450]" style={{ fontStyle: "italic" }}>
454	            {extraction.raw_text_preserved}
455	          </div>
456	        )}
457	      </div>
458	
459	      {/* Run again */}
460	      <div className="pt-1">
461	        <button
462	          type="button"
463	          onClick={onRunAgain}
464	          className="text-[12px] text-brand-600 hover:text-brand-800 transition-colors underline underline-offset-2"
465	        >
466	          Run Ada again
467	        </button>
468	      </div>
469	    </div>
470	  );
471	}
472	
473	// ─── Main component ──────────────────────────────────────────────────────────
474	
475	export function AdaSection({
476	  dealId,
477	  dealNotesFreetext,
478	  existingExtraction,
479	  existingFlags,
480	}: {
481	  dealId: string;
482	  dealNotesFreetext: string | null;
483	  existingExtraction: AdaExtraction | null;
484	  existingFlags: AdaFlag[] | null;
485	}) {
486	  const hasExisting = existingExtraction != null;
487	  const router = useRouter();
488	
489	  const [pastedText, setPastedText] = useState("");
490	  const [mode, setMode] = useState<AdaMode>(hasExisting ? "update" : "initial");
491	  const [isLoading, setIsLoading] = useState(false);
492	  const [loadingPhase, setLoadingPhase] = useState(0);
493	  const [result, setResult] = useState<AdaApiSuccess | null>(null);
494	  const [error, setError] = useState<string | null>(null);
495	  const [showForm, setShowForm] = useState(!hasExisting);
496	
497	  const loadingIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
498	
499	  useEffect(() => {
500	    if (isLoading) {
501	      setLoadingPhase(0);
502	      loadingIntervalRef.current = setInterval(() => {
503	        setLoadingPhase((p) => (p + 1) % LOADING_MESSAGES.length);
504	      }, 2000);
505	    } else {
506	      if (loadingIntervalRef.current) {
507	        clearInterval(loadingIntervalRef.current);
508	        loadingIntervalRef.current = null;
509	      }
510	    }
511	    return () => {
512	      if (loadingIntervalRef.current) clearInterval(loadingIntervalRef.current);
513	    };
514	  }, [isLoading]);
515	
516	  // If we have a prior result from this session, show it.
517	  // Otherwise show existing extraction from server if available.
518	  const displayExtraction = result?.extraction ?? existingExtraction ?? null;
519	  const displayFlags = result?.flags ?? existingFlags ?? null;
520	  const displayMode = result?.mode_used ?? (hasExisting ? "update" : "initial");
521	
522	  async function handleSubmit(e: React.FormEvent) {
523	    e.preventDefault();
524	    if (!pastedText.trim() || isLoading) return;
525	
526	    setIsLoading(true);
527	    setError(null);
528	
529	    try {
530	      const res = await fetch("/api/ada/extract", {
531	        method: "POST",
532	        headers: { "Content-Type": "application/json" },
533	        body: JSON.stringify({
534	          deal_id: dealId,
535	          pasted_text: pastedText,
536	          mode,
537	        }),
538	      });
539	
540	      const data = await res.json();
541	
542	      if (!res.ok || "error" in data) {
543	        setError(data.error ?? "Something went wrong. Please try again.");
544	      } else {
545	        setResult(data as AdaApiSuccess);
546	        setShowForm(false);
547	        router.refresh();
548	      }
549	    } catch {
550	      setError("Network error. Your input has been saved if it reached the server.");
551	    } finally {
552	      setIsLoading(false);
553	    }
554	  }
555	
556	  function handleRunAgain() {
557	    setShowForm(true);
558	    setPastedText("");
559	    setError(null);
560	  }
561	
562	  return (
563	    <div className="mt-8">
564	      <div className="flex items-center gap-2 mb-4">
565	        <Sparkles className="h-4 w-4 text-brand-600" />
566	        <h2 className="text-[13px] font-semibold text-ink-900 tracking-tight">Ask Ada</h2>
567	        <span className="text-[11px] text-ink-400">· Deal disambiguation assistant</span>
568	      </div>
569	
570	      {/* Paste form */}
571	      {showForm && (
572	        <Card>
573	          <CardContent className="pt-5">
574	            <form onSubmit={handleSubmit} className="space-y-4">
575	              <div>
576	                <div className="flex items-baseline justify-between mb-2">
577	                  <label
578	                    htmlFor="ada-paste"
579	                    className="eyebrow text-[10px] text-ink-500"
580	                  >
581	                    Paste the latest deal email or agent communication
582	                  </label>
583	                  {dealNotesFreetext && (
584	                    <button
585	                      type="button"
586	                      onClick={() => setPastedText(dealNotesFreetext)}
587	                      className="text-[11px] text-brand-600 hover:text-brand-800 transition-colors"
588	                    >
589	                      ↓ Insert current deal notes
590	                    </button>
591	                  )}
592	                </div>
593	                <textarea
594	                  id="ada-paste"
595	                  value={pastedText}
596	                  onChange={(e) => setPastedText(e.target.value)}
597	                  placeholder="Paste deal email here..."
598	                  rows={6}
599	                  className="w-full rounded-md ring-1 ring-ink-200/80 bg-canvas-soft px-4 py-3 text-[13px] text-ink-900 placeholder:text-ink-300 resize-y focus:outline-none focus:ring-2 focus:ring-brand-400/60 leading-relaxed"
600	                  disabled={isLoading}
601	                />
602	              </div>
603	
604	              {/* Mode selector — only shown when a prior extraction exists */}
605	              {hasExisting && (
606	                <div className="flex items-center gap-4">
607	                  <span className="eyebrow text-[10px] text-ink-500">Mode</span>
608	                  {(["update", "replace", "initial"] as const).map((m) => (
609	                    <label
610	                      key={m}
611	                      className={cn(
612	                        "flex items-center gap-1.5 text-[12.5px] cursor-pointer",
613	                        mode === m ? "text-ink-900" : "text-ink-500",
614	                        isLoading && "opacity-50 pointer-events-none",
615	                      )}
616	                    >
617	                      <input
618	                        type="radio"
619	                        name="ada-mode"
620	                        value={m}
621	                        checked={mode === m}
622	                        onChange={() => setMode(m)}
623	                        className="accent-brand-600"
624	                        disabled={isLoading}
625	                      />
626	                      <span className="capitalize">{m}</span>
627	                    </label>
628	                  ))}
629	                </div>
630	              )}
631	
632	              {error && (
633	                <div className="rounded-md ring-1 ring-rose-200 bg-rose-50/60 px-4 py-3 text-[12.5px] text-rose-800">
634	                  {error}
635	                </div>
