// Re-fetching here ensures the current row's snapshot is included.
const historyForUI = await db
  .select()
  .from(dealNotesHistory)
  .where(eq(dealNotesHistory.dealId, deal_id))
  .orderBy(desc(dealNotesHistory.pastedAt))
  .limit(3);

