272	            flags={flagMap.get("hospitality_cap")}
273	          />
274	        )}
275	      </CardContent>
276	    </Card>
277	  );
278	}
279	
280	function EscalatorsCard({
281	  extraction,
282	  flagMap,
283	}: {
284	  extraction: AdaExtraction;
285	  flagMap: Map<AdaFieldAffected, AdaFlag[]>;
286	}) {
287	  const hasAny =
288	    extraction.ratchet != null ||
289	    extraction.walkout_pot != null ||
290	    extraction.tiered_net_split != null;
291	  if (!hasAny) return null;
292	
293	  return (
294	    <Card>
295	      <CardHeader>
296	        <CardTitle>Escalators</CardTitle>
297	      </CardHeader>
