300	          <div>
301	            <div className="eyebrow text-[10px] text-ink-500 mb-2">Ratchet</div>
302	            <div className="text-[13px] text-ink-800 leading-relaxed">
303	              {formatPct(extraction.ratchet.base_percent)} base →{" "}
304	              {formatPct(extraction.ratchet.cap_percent)} above{" "}
305	              {formatPct(extraction.ratchet.trigger_capacity_pct)} capacity
306	            </div>
307	            {flagMap.get("ratchet")?.map((f, i) => <FlagItem key={i} flag={f} inline />)}
308	          </div>
309	        )}
310	        {extraction.walkout_pot && (
311	          <div>
312	            <div className="eyebrow text-[10px] text-ink-500 mb-2">Walkout pot</div>
313	            <div className="text-[13px] text-ink-800 leading-relaxed">
314	              100% of gross above {formatMoney(extraction.walkout_pot.threshold_amount)}
315	              {extraction.walkout_pot.threshold_source === "computed" && (
316	                <span className="ml-1.5 text-[11px] text-ink-400">(computed threshold)</span>
317	              )}
318	            </div>
