320	          </div>
321	        )}
322	        {extraction.tiered_net_split && (
323	          <div>
324	            <div className="eyebrow text-[10px] text-ink-500 mb-2">Tiered net split</div>
325	            <div className="text-[13px] text-ink-800 leading-relaxed">
326	              {formatPct(extraction.tiered_net_split.low_percent)} up to{" "}
327	              {formatMoney(extraction.tiered_net_split.threshold_gross)} gross, then{" "}
328	              {formatPct(extraction.tiered_net_split.high_percent)}
329	            </div>
330	          </div>
331	        )}
332	      </CardContent>
333	    </Card>
334	  );
335	}
336	
337	function BonusesCard({
338	  extraction,
339	  flagMap,
340	}: {
341	  extraction: AdaExtraction;
342	  flagMap: Map<AdaFieldAffected, AdaFlag[]>;
343	}) {
344	  if (!extraction.bonuses || extraction.bonuses.length === 0) return null;
345	
346	  return (
347	    <Card>
348	      <CardHeader>
349	        <CardTitle>Bonuses</CardTitle>
350	      </CardHeader>
351	      <CardContent>
352	        <ul className="space-y-3">
353	          {extraction.bonuses.map((b, i) => (
354	            <li key={i} className="text-[13px] text-ink-800 leading-relaxed">
355	              <span className="inline-flex items-center px-1.5 py-px rounded text-[9px] font-mono uppercase tracking-wider bg-white ring-1 ring-brand-200/50 text-brand-800 mr-2">
356	                {b.type === "gross_threshold"
357	                  ? "gross"
358	                  : b.type === "attendance_threshold"
359	                    ? "attend"
360	                    : "sellout"}
361	              </span>
362	              {b.trigger}
363	              {" · "}
364	              <span className="font-mono tabular">{formatMoney(b.amount)}</span>
365	              {b.stacks && (
366	                <span className="ml-1.5 text-[11px] text-ink-400">stacks</span>
367	              )}
368	            </li>
