376	
377	// ─── Delta panel (Update mode) ───────────────────────────────────────────────
378	
379	function DeltaPanel({ extraction }: { extraction: AdaExtraction }) {
380	  const changes = extraction.changes_from_previous;
381	  if (!changes || changes.length === 0) return null;
382	
383	  return (
384	    <div className="rounded-lg ring-1 ring-sky-200/70 bg-sky-50/50 px-5 py-4">
385	      <div className="eyebrow text-[10px] text-sky-700 mb-3">Changes from prior version</div>
386	      <ul className="space-y-3">
387	        {changes.map((c, i) => (
388	          <li key={i} className="text-[12.5px] text-ink-800">
389	            <div className="font-mono text-[11px] text-ink-500 mb-0.5">{c.field_path}</div>
390	            <div className="flex items-center gap-2 flex-wrap">
391	              <span className="text-ink-500 line-through">{String(c.previous_value ?? "—")}</span>
392	              <ArrowRight className="h-3 w-3 text-ink-400 shrink-0" />
393	              <span className="font-medium text-ink-900">{String(c.new_value ?? "—")}</span>
394	            </div>
395	            {c.evidence_quote && (
396	              <blockquote className="mt-1 pl-2 border-l-2 border-sky-300 text-[11px] text-sky-700 italic">
397	                &ldquo;{c.evidence_quote}&rdquo;
398	              </blockquote>
399	            )}
400	          </li>
401	        ))}
402	      </ul>
403	    </div>
404	  );
405	}
406	
407	// ─── Extraction result display ───────────────────────────────────────────────
408	
409	function ExtractionResult({
410	  extraction,
411	  flags,
412	  modeUsed,
413	}: {
414	  extraction: AdaExtraction;
415	  flags: AdaFlag[];
416	  modeUsed: AdaMode;
417	}) {
418	  const [showRawText, setShowRawText] = useState(false);
419	
420	  const flagMap = new Map<AdaFieldAffected, AdaFlag[]>();
421	  for (const f of flags) {
422	    const existing = flagMap.get(f.field_affected) ?? [];
423	    flagMap.set(f.field_affected, [...existing, f]);
424	  }
425	
426	  const globalFlags = flagMap.get("global") ?? [];
427	
428	  return (
429	    <div className="space-y-4">
430	      {globalFlags.length > 0 && (
431	        <div className="space-y-2">
432	          {globalFlags.map((f, i) => <FlagItem key={i} flag={f} />)}
433	        </div>
434	      )}
435	
436	      {modeUsed === "update" && <DeltaPanel extraction={extraction} />}
437	
438	      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
439	        <CoreTermsCard extraction={extraction} flagMap={flagMap} />
440	        <PercentageSplitCard extraction={extraction} flagMap={flagMap} />
441	        <CapsCard extraction={extraction} flagMap={flagMap} />
442	        <EscalatorsCard extraction={extraction} flagMap={flagMap} />
443	        <BonusesCard extraction={extraction} flagMap={flagMap} />
444	      </div>
445	
446	      {extraction.complex_structure && (
447	        <div className="flex items-center gap-2 text-[12px] text-ink-500 pt-1">
448	          <Info className="h-3.5 w-3.5" />
449	          Ada marked this deal as complex — it may not fit the standard schema cleanly. Review the original text.
450	        </div>
451	      )}
452	
453	      <div className="border-t border-ink-100/80 pt-3">
454	        <button
455	          type="button"
456	          onClick={() => setShowRawText((v) => !v)}
457	          className="flex items-center gap-1.5 text-[11.5px] text-ink-400 hover:text-ink-700 transition-colors"
458	        >
459	          {showRawText ? <ChevronUp className="h-3.5 w-3.5" /> : <ChevronDown className="h-3.5 w-3.5" />}
460	          {showRawText ? "Hide" : "View"} original pasted text
461	        </button>
462	        {showRawText && (
463	          <div className="mt-2 text-[12px] text-ink-700 bg-canvas-soft rounded-lg p-4 ring-1 ring-ink-200/50 leading-relaxed whitespace-pre-wrap font-[450]" style={{ fontStyle: "italic" }}>
464	            {extraction.raw_text_preserved}
465	          </div>
466	        )}
467	      </div>
468	    </div>
469	  );
470	}
471	
472	// ─── History panel ───────────────────────────────────────────────────────────
473	
474	function HistoryEntryItem({ entry }: { entry: AdaHistoryEntry }) {
475	  const [expanded, setExpanded] = useState(false);
476	
477	  const snippet =
478	    entry.pastedText.length > 80
479	      ? entry.pastedText.slice(0, 80) + "…"
480	      : entry.pastedText;
481	
482	  let snapshotData: { extraction: AdaExtraction; flags: AdaFlag[] } | null = null;
483	  if (entry.extractionSnapshotJson) {
484	    try {
485	      snapshotData = JSON.parse(entry.extractionSnapshotJson);
486	    } catch {
487	      // malformed snapshot — show failure state
488	    }
489	  }
490	
491	  return (
492	    <div className="rounded-lg ring-1 ring-ink-200/60 bg-white px-4 py-3">
493	      <div className="flex items-start justify-between gap-3">
494	        <div className="min-w-0 flex-1">
495	          <div className="flex items-center gap-2 mb-1">
496	            <span className="text-[11px] text-ink-500">{formatTimestamp(entry.pastedAt)}</span>
497	            <span className="text-ink-300">·</span>
498	            <span className="text-[11px] text-ink-500">{MODE_LABELS[entry.modeUsed]}</span>
499	          </div>
500	          <p className="text-[12px] text-ink-600 leading-relaxed">{snippet}</p>
501	        </div>
502	        <button
503	          type="button"
504	          onClick={() => setExpanded((v) => !v)}
505	          className="flex items-center gap-1 text-[11px] text-ink-400 hover:text-ink-700 transition-colors shrink-0 mt-0.5"
506	          aria-label={expanded ? "Collapse" : "Expand"}
507	        >
508	          {expanded ? <ChevronUp className="h-3.5 w-3.5" /> : <ChevronDown className="h-3.5 w-3.5" />}
509	        </button>
510	      </div>
511	
512	      {expanded && (
513	        <div className="mt-3 pt-3 border-t border-ink-100/80">
514	          {snapshotData ? (
515	            <ExtractionResult
516	              extraction={snapshotData.extraction}
517	              flags={snapshotData.flags}
518	              modeUsed={entry.modeUsed}
519	            />
520	          ) : (
521	            <p className="text-[12px] text-ink-400 italic">
522	              Extraction failed — input preserved
523	            </p>
524	          )}
525	        </div>
526	      )}
527	    </div>
528	  );
529	}
530	
531	// ─── Main component ──────────────────────────────────────────────────────────
532	
533	export function AdaSection({
534	  dealId,
535	  dealNotesFreetext,
536	  existingExtraction,
537	  existingFlags,
538	  existingHistory,
539	}: {
540	  dealId: string;
541	  dealNotesFreetext: string | null;
542	  existingExtraction: AdaExtraction | null;
543	  existingFlags: AdaFlag[] | null;
544	  existingHistory: AdaHistoryEntry[];
545	}) {
546	  const router = useRouter();
547	
548	  const [pastedText, setPastedText] = useState("");
549	  const [mode, setMode] = useState<AdaMode>(existingExtraction != null ? "update" : "initial");
550	  const [isLoading, setIsLoading] = useState(false);
551	  const [loadingPhase, setLoadingPhase] = useState(0);
552	  const [result, setResult] = useState<AdaApiSuccess | null>(null);
553	  const [error, setError] = useState<string | null>(null);
554	  const [history, setHistory] = useState<AdaHistoryEntry[]>(existingHistory);
555	
556	  const loadingIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
557	
558	  useEffect(() => {
559	    if (isLoading) {
560	      setLoadingPhase(0);
561	      loadingIntervalRef.current = setInterval(() => {
562	        setLoadingPhase((p) => (p + 1) % LOADING_MESSAGES.length);
563	      }, 2000);
564	    } else {
565	      if (loadingIntervalRef.current) {
566	        clearInterval(loadingIntervalRef.current);
567	        loadingIntervalRef.current = null;
568	      }
569	    }
570	    return () => {
571	      if (loadingIntervalRef.current) clearInterval(loadingIntervalRef.current);
572	    };
573	  }, [isLoading]);
574	
575	  // A prior extraction exists either from the server or from this session.
576	  const hasExisting = existingExtraction != null || result != null;
577	
578	  const displayExtraction = result?.extraction ?? existingExtraction ?? null;
579	  const displayFlags = result?.flags ?? existingFlags ?? null;
580	  const displayMode = result?.mode_used ?? (existingExtraction != null ? "update" : "initial");
581	
582	  async function handleSubmit(e: React.FormEvent) {
583	    e.preventDefault();
584	    if (!pastedText.trim() || isLoading) return;
585	
586	    setIsLoading(true);
587	    setError(null);
588	
589	    try {
590	      const res = await fetch("/api/ada/extract", {
591	        method: "POST",
592	        headers: { "Content-Type": "application/json" },
593	        body: JSON.stringify({
594	          deal_id: dealId,
595	          pasted_text: pastedText,
596	          mode,
597	        }),
598	      });
599	
600	      const data = await res.json();
601	
602	      if (!res.ok || "error" in data) {
603	        setError(data.error ?? "Something went wrong. Please try again.");
604	      } else {
605	        const success = data as AdaApiSuccess;
606	        setResult(success);
607	        setPastedText("");
608	        if (success.history) setHistory(success.history);
609	        router.refresh();
610	      }
611	    } catch {
612	      setError("Network error. Your input has been saved if it reached the server.");
613	    } finally {
614	      setIsLoading(false);
615	    }
616	  }
617	
618	  return (
619	    <div className="mt-8">
620	      <div className="flex items-center gap-2 mb-4">
621	        <Sparkles className="h-4 w-4 text-brand-600" />
622	        <h2 className="text-[13px] font-semibold text-ink-900 tracking-tight">Ask Ada</h2>
623	        <span className="text-[11px] text-ink-400">· Deal disambiguation assistant</span>
624	      </div>
625	
626	      {/* Current extraction results */}
627	      {displayExtraction && displayFlags && (
628	        <div className="mb-6">
629	          <ExtractionResult
630	            extraction={displayExtraction}
631	            flags={displayFlags}
632	            modeUsed={displayMode as AdaMode}
633	          />
634	        </div>
635	      )}
636	
637	      {/* Version history — last 3 runs */}
638	      {history.length > 0 && (
639	        <div className="mb-6">
640	          <div className="eyebrow text-[10px] text-ink-500 mb-2">Recent runs</div>
641	          <div className="space-y-2">
642	            {history.slice(0, 3).map((entry) => (
643	              <HistoryEntryItem key={entry.id} entry={entry} />
644	            ))}
645	          </div>
646	        </div>
647	      )}
648	
649	      {/* Paste form — always visible */}
650	      <Card>
651	        <CardContent className="pt-5">
652	          <form onSubmit={handleSubmit} className="space-y-4">
653	            <div>
654	              <div className="flex items-baseline justify-between mb-2">
655	                <label
656	                  htmlFor="ada-paste"
657	                  className="eyebrow text-[10px] text-ink-500"
658	                >
659	                  Paste the latest deal email or agent communication
660	                </label>
661	                {dealNotesFreetext && (
662	                  <button
663	                    type="button"
664	                    onClick={() => setPastedText(dealNotesFreetext)}
665	                    className="text-[11px] text-brand-600 hover:text-brand-800 transition-colors"
666	                  >
667	                    ↓ Insert current deal notes
668	                  </button>
669	                )}
670	              </div>
671	              <textarea
672	                id="ada-paste"
673	                value={pastedText}
674	                onChange={(e) => setPastedText(e.target.value)}
675	                placeholder="Paste deal email here..."
676	                rows={6}
677	                className="w-full rounded-md ring-1 ring-ink-200/80 bg-canvas-soft px-4 py-3 text-[13px] text-ink-900 placeholder:text-ink-300 resize-y focus:outline-none focus:ring-2 focus:ring-brand-400/60 leading-relaxed"
678	                disabled={isLoading}
679	              />
680	            </div>
681	
682	            {/* Mode selector — shown once a prior extraction exists */}
683	            {hasExisting && (
684	              <div className="flex items-center gap-4">
685	                <span className="eyebrow text-[10px] text-ink-500">Mode</span>
686	                {(["update", "replace", "initial"] as const).map((m) => (
687	                  <label
688	                    key={m}
689	                    className={cn(
690	                      "flex items-center gap-1.5 text-[12.5px] cursor-pointer",
691	                      mode === m ? "text-ink-900" : "text-ink-500",
692	                      isLoading && "opacity-50 pointer-events-none",
693	                    )}
694	                  >
695	                    <input
696	                      type="radio"
697	                      name="ada-mode"
698	                      value={m}
699	                      checked={mode === m}
700	                      onChange={() => setMode(m)}
701	                      className="accent-brand-600"
702	                      disabled={isLoading}
703	                    />
704	                    <span className="capitalize">{m}</span>
705	                  </label>
706	                ))}
707	              </div>
708	            )}
709	
710	            {error && (
711	              <div className="rounded-md ring-1 ring-rose-200 bg-rose-50/60 px-4 py-3 text-[12.5px] text-rose-800">
712	                {error}
713	              </div>
714	            )}
715	
716	            <Button
717	              type="submit"
718	              variant="brand"
719	              disabled={!pastedText.trim() || isLoading}
720	            >
721	              {isLoading ? (
722	                <span className="flex items-center gap-2">
723	                  <span className="inline-block h-3.5 w-3.5 rounded-full border-2 border-white/30 border-t-white animate-spin" />
724	                  {LOADING_MESSAGES[loadingPhase]}
725	                </span>
726	              ) : (
727	                <>
728	                  <Sparkles className="h-3.5 w-3.5" />
729	                  Ask Ada
730	                </>
731	              )}
732	            </Button>
733	          </form>
734	        </CardContent>
735	      </Card>
736	    </div>
737	  );
738	}
