import { NextResponse } from "next/server";
import { GoogleGenerativeAI } from "@google/generative-ai";
import { db } from "@/db";
import { deals, dealNotesHistory } from "@/db/schema";
import { eq, asc, desc, inArray } from "drizzle-orm";
import { buildSystemPrompt, buildUserMessage } from "@/lib/ada/prompts";
import { geminiResponseSchema } from "@/lib/ada/schemas";
import type {
  AdaApiRequest,
  AdaExtraction,
  AdaFlag,
  AdaMode,
} from "@/lib/ada/types";

const BRACKETED_UPDATE_RE = /\[[\s\S]*?\]/;

function makeBracketedUpdateFlag(match: string): AdaFlag {
  return {
    flag_class: "bracketed_update",
    field_affected: "global",
    description:
      "The pasted text contains a bracketed note that may represent a post-hoc update to deal terms. Verify that the structured fields reflect the most recent version.",
    evidence_quote: match,
    suggested_question: null,
  };
}

function makeModeFallbackFlag(): AdaFlag {
  return {
    flag_class: "mode_fallback",
    field_affected: "global",
    description:
      "Update mode was requested but no prior extraction exists for this deal. Ada ran as Initial extraction instead.",
    evidence_quote: null,
    suggested_question: null,
  };
}

export async function POST(req: Request) {
  let body: AdaApiRequest;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const { deal_id, pasted_text, mode } = body;
  if (!deal_id || !pasted_text || !mode) {
    return NextResponse.json(
      { error: "Missing required fields: deal_id, pasted_text, mode" },
      { status: 400 },
    );
  }

  // Step 1 (Transaction A): persist the raw input before doing anything else.
  // This row is never deleted — even if Gemini fails later, Mariana's input is safe.
  let historyId: string;
  try {
    historyId = crypto.randomUUID();
    await db.transaction(async (tx) => {
      await tx.insert(dealNotesHistory).values({
        id: historyId,
        dealId: deal_id,
        pastedText: pasted_text,
        modeUsed: mode,
        pastedAt: new Date(),
      });
    });
  } catch (err) {
    console.error("[Ada] Failed to persist history row:", err);
    return NextResponse.json(
      { error: "Failed to save input. Please try again." },
      { status: 500 },
    );
  }

  // Step 2: deterministic bracketed_update check (before Gemini).
  const pendingFlags: AdaFlag[] = [];
  const bracketMatch = pasted_text.match(BRACKETED_UPDATE_RE);
  if (bracketMatch) {
    pendingFlags.push(makeBracketedUpdateFlag(bracketMatch[0]));
  }

  // Step 3: mode resolution — if Update requested but no prior extraction exists,
  // fall back to Initial and queue an advisory flag.
  let resolvedMode: AdaMode = mode;
  let priorExtraction: AdaExtraction | null = null;

  const dealRow = await db.query.deals.findFirst({
    where: eq(deals.id, deal_id),
  });

  if (!dealRow) {
    return NextResponse.json(
      { error: "Deal not found.", history_id: historyId },
      { status: 404 },
    );
  }

  if (dealRow.extractionJson) {
    try {
      priorExtraction = JSON.parse(dealRow.extractionJson) as AdaExtraction;
    } catch {
      priorExtraction = null;
    }
  }

  if (mode === "update" && !priorExtraction) {
    resolvedMode = "initial";
    pendingFlags.push(makeModeFallbackFlag());
  }

  // Replace mode always treats the new email as a fresh start.
  if (mode === "replace") {
    priorExtraction = null;
  }

  // Fetch full history (oldest → newest) for use in the Update mode prompt.
  // This is done after Txn A, so the current row is included but its snapshot
  // is still null — it will be filtered out in buildUserMessage.
  const fullHistory = await db
    .select()
    .from(dealNotesHistory)
    .where(eq(dealNotesHistory.dealId, deal_id))
    .orderBy(asc(dealNotesHistory.pastedAt));

  // Steps 4–5: build and send the Gemini request.
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) {
    return NextResponse.json(
      { error: "Gemini API key not configured.", history_id: historyId },
      { status: 500 },
    );
  }

  const genAI = new GoogleGenerativeAI(apiKey);
  const model = genAI.getGenerativeModel({
    model: "gemini-2.5-flash",
    systemInstruction: buildSystemPrompt(),
    generationConfig: {
      responseMimeType: "application/json",
      responseSchema: geminiResponseSchema,
    },
  });

  let extraction: AdaExtraction;
  let geminiFlags: AdaFlag[];
  try {
    // Exclude the current in-flight row (null snapshot) and pass at most the
  // 3 most-recent prior rows (oldest → newest) as history context.
  const priorRowsForGemini = fullHistory
    .filter((h) => h.id !== historyId)
    .slice(-3);

  const userMessage = buildUserMessage(
      resolvedMode,
      pasted_text,
      priorExtraction,
      priorRowsForGemini,
    );
    const result = await model.generateContent(userMessage);
    const raw = result.response.text();
    const parsed = JSON.parse(raw) as { extraction: AdaExtraction; flags: AdaFlag[] };
    extraction = parsed.extraction;
    geminiFlags = parsed.flags ?? [];
  } catch (err) {
    console.error("[Ada] Gemini call failed:", err);
    return NextResponse.json(
      {
        error: "Ada could not process the email. Your input has been saved — try again.",
        history_id: historyId,
      },
      { status: 502 },
    );
  }

  // Step 6 (Transaction B): append deterministic flags and persist results.
  const allFlags: AdaFlag[] = [...geminiFlags, ...pendingFlags];
  const extractionJson = JSON.stringify(extraction);
  const flagsJson = JSON.stringify(allFlags);

  try {
    await db.transaction(async (tx) => {
      await tx
        .update(dealNotesHistory)
        .set({ extractionSnapshotJson: JSON.stringify({ extraction, flags: allFlags }) })
        .where(eq(dealNotesHistory.id, historyId));

      await tx
        .update(deals)
        .set({
          extractionJson,
          ambiguityFlagsJson: flagsJson,
        })
        .where(eq(deals.id, deal_id));
    });
  } catch (err) {
    console.error("[Ada] Failed to persist extraction results:", err);
    return NextResponse.json(
      {
        error: "Ada extracted the deal but failed to save the results. Your original input is preserved.",
        history_id: historyId,
      },
      { status: 500 },
    );
  }

  // Enforce 4-row cap per deal. fullHistory already includes the current row
  // (inserted in Txn A); if the total exceeds 4, delete the oldest rows.
  if (fullHistory.length > 4) {
    const idsToDelete = fullHistory
      .slice(0, fullHistory.length - 4)
      .map((h) => h.id);
    await db
      .delete(dealNotesHistory)
      .where(inArray(dealNotesHistory.id, idsToDelete));
  }

  // Build priorHistory from the in-memory list: exclude the current row,
  // take at most 3, flip to most-recent-first. No re-fetch needed because
  // the prior rows' snapshots were not modified in this request.
  const priorHistory = fullHistory
    .filter((h) => h.id !== historyId)
    .slice(-3)
    .reverse()
    .map((h) => ({
      id: h.id,
      pastedText: h.pastedText,
      modeUsed: h.modeUsed,
      pastedAt: (h.pastedAt as Date).toISOString(),
      extractionSnapshotJson: h.extractionSnapshotJson,
    }));

  return NextResponse.json({
    extraction,
    flags: allFlags,
    mode_used: resolvedMode,
    history_id: historyId,
    priorHistory,
  });
}

import { NextResponse } from "next/server";
import { GoogleGenerativeAI } from "@google/generative-ai";
import { db } from "@/db";
import { deals, dealNotesHistory } from "@/db/schema";
import { eq, asc, desc, inArray } from "drizzle-orm";
import { buildSystemPrompt, buildUserMessage } from "@/lib/ada/prompts";
import { geminiResponseSchema } from "@/lib/ada/schemas";
import type {
  AdaApiRequest,
  AdaExtraction,
  AdaFlag,
  AdaMode,
} from "@/lib/ada/types";

const BRACKETED_UPDATE_RE = /\[[\s\S]*?\]/;

function makeBracketedUpdateFlag(match: string): AdaFlag {
  return {
    flag_class: "bracketed_update",
    field_affected: "global",
    description:
      "The pasted text contains a bracketed note that may represent a post-hoc update to deal terms. Verify that the structured fields reflect the most recent version.",
    evidence_quote: match,
    suggested_question: null,
  };
}

function makeModeFallbackFlag(): AdaFlag {
  return {
    flag_class: "mode_fallback",
    field_affected: "global",
    description:
      "Update mode was requested but no prior extraction exists for this deal. Ada ran as Initial extraction instead.",
    evidence_quote: null,
    suggested_question: null,
  };
}

export async function POST(req: Request) {
  let body: AdaApiRequest;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const { deal_id, pasted_text, mode } = body;
  if (!deal_id || !pasted_text || !mode) {
    return NextResponse.json(
      { error: "Missing required fields: deal_id, pasted_text, mode" },
      { status: 400 },
    );
  }

  // Step 1 (Transaction A): persist the raw input before doing anything else.
  // This row is never deleted — even if Gemini fails later, Mariana's input is safe.
  let historyId: string;
  try {
    historyId = crypto.randomUUID();
    await db.transaction(async (tx) => {
      await tx.insert(dealNotesHistory).values({
        id: historyId,
        dealId: deal_id,
        pastedText: pasted_text,
        modeUsed: mode,
        pastedAt: new Date(),
      });
    });
  } catch (err) {
    console.error("[Ada] Failed to persist history row:", err);
    return NextResponse.json(
      { error: "Failed to save input. Please try again." },
      { status: 500 },
    );
  }

  // Step 2: deterministic bracketed_update check (before Gemini).
  const pendingFlags: AdaFlag[] = [];
  const bracketMatch = pasted_text.match(BRACKETED_UPDATE_RE);
  if (bracketMatch) {
    pendingFlags.push(makeBracketedUpdateFlag(bracketMatch[0]));
  }

  // Step 3: mode resolution — if Update requested but no prior extraction exists,
  // fall back to Initial and queue an advisory flag.
  let resolvedMode: AdaMode = mode;
  let priorExtraction: AdaExtraction | null = null;

  const dealRow = await db.query.deals.findFirst({
    where: eq(deals.id, deal_id),
  });

  if (!dealRow) {
    return NextResponse.json(
      { error: "Deal not found.", history_id: historyId },
      { status: 404 },
    );
  }

  if (dealRow.extractionJson) {
    try {
      priorExtraction = JSON.parse(dealRow.extractionJson) as AdaExtraction;
    } catch {
      priorExtraction = null;
    }
  }

  if (mode === "update" && !priorExtraction) {
    resolvedMode = "initial";
    pendingFlags.push(makeModeFallbackFlag());
  }

  // Replace mode always treats the new email as a fresh start.
  if (mode === "replace") {
    priorExtraction = null;
  }

  // Fetch full history (oldest → newest) for use in the Update mode prompt.
  // This is done after Txn A, so the current row is included but its snapshot
  // is still null — it will be filtered out in buildUserMessage.
  const fullHistory = await db
    .select()
    .from(dealNotesHistory)
    .where(eq(dealNotesHistory.dealId, deal_id))
    .orderBy(asc(dealNotesHistory.pastedAt));

  // Steps 4–5: build and send the Gemini request.
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) {
    return NextResponse.json(
      { error: "Gemini API key not configured.", history_id: historyId },
      { status: 500 },
    );
  }

  const genAI = new GoogleGenerativeAI(apiKey);
  const model = genAI.getGenerativeModel({
    model: "gemini-2.5-flash",
    systemInstruction: buildSystemPrompt(),
    generationConfig: {
      responseMimeType: "application/json",
      responseSchema: geminiResponseSchema,
    },
  });

  let extraction: AdaExtraction;
  let geminiFlags: AdaFlag[];
  try {
    // Exclude the current in-flight row (null snapshot) and pass at most the
  // 3 most-recent prior rows (oldest → newest) as history context.
  const priorRowsForGemini = fullHistory
    .filter((h) => h.id !== historyId)
    .slice(-3);

  const userMessage = buildUserMessage(
      resolvedMode,
      pasted_text,
      priorExtraction,
      priorRowsForGemini,
    );
    const result = await model.generateContent(userMessage);
    const raw = result.response.text();
    const parsed = JSON.parse(raw) as { extraction: AdaExtraction; flags: AdaFlag[] };
    extraction = parsed.extraction;
    geminiFlags = parsed.flags ?? [];
  } catch (err) {
    console.error("[Ada] Gemini call failed:", err);
    return NextResponse.json(
      {
        error: "Ada could not process the email. Your input has been saved — try again.",
        history_id: historyId,
      },
      { status: 502 },
    );
  }

  // Step 6 (Transaction B): append deterministic flags and persist results.
  const allFlags: AdaFlag[] = [...geminiFlags, ...pendingFlags];
  const extractionJson = JSON.stringify(extraction);
  const flagsJson = JSON.stringify(allFlags);

  try {
    await db.transaction(async (tx) => {
      await tx
        .update(dealNotesHistory)
        .set({ extractionSnapshotJson: JSON.stringify({ extraction, flags: allFlags }) })
        .where(eq(dealNotesHistory.id, historyId));

      await tx
        .update(deals)
        .set({
          extractionJson,
          ambiguityFlagsJson: flagsJson,
        })
        .where(eq(deals.id, deal_id));
    });
  } catch (err) {
    console.error("[Ada] Failed to persist extraction results:", err);
    return NextResponse.json(
      {
        error: "Ada extracted the deal but failed to save the results. Your original input is preserved.",
        history_id: historyId,
      },
      { status: 500 },
    );
  }

  // Enforce 4-row cap per deal. fullHistory already includes the current row
  // (inserted in Txn A); if the total exceeds 4, delete the oldest rows.
  if (fullHistory.length > 4) {
    const idsToDelete = fullHistory
      .slice(0, fullHistory.length - 4)
      .map((h) => h.id);
    await db
      .delete(dealNotesHistory)
      .where(inArray(dealNotesHistory.id, idsToDelete));
  }

  // Build priorHistory from the in-memory list: exclude the current row,
  // take at most 3, flip to most-recent-first. No re-fetch needed because
  // the prior rows' snapshots were not modified in this request.
  const priorHistory = fullHistory
    .filter((h) => h.id !== historyId)
    .slice(-3)
    .reverse()
    .map((h) => ({
      id: h.id,
      pastedText: h.pastedText,
      modeUsed: h.modeUsed,
      pastedAt: (h.pastedAt as Date).toISOString(),
      extractionSnapshotJson: h.extractionSnapshotJson,
    }));

  return NextResponse.json({
    extraction,
    flags: allFlags,
    mode_used: resolvedMode,
    history_id: historyId,
    priorHistory,
  });
}

export type AdaMode = "initial" | "update" | "replace";

export type AdaDealType =
  | "flat"
  | "vs"
  | "percentage_of_net"
  | "percentage_of_gross"
  | "door";

export type AdaFlagClass =
  | "ambiguous_net"
  | "external_reference"
  | "computed_threshold"
  | "missing_overage"
  | "unresolved_reference"
  | "bracketed_update"
  | "mode_fallback"
  | "other";

export type AdaFieldAffected =
  | "guarantee_amount"
  | "percentage"
  | "percentage_basis"
  | "expense_cap"
  | "hospitality_cap"
  | "ratchet"
  | "walkout_pot"
  | "bonuses"
  | "global";

export interface AdaRatchet {
  base_percent: number;
  cap_percent: number;
  trigger_capacity_pct: number;
}

export interface AdaWalkoutPot {
  threshold_amount: number;
  threshold_source: "stated" | "computed";
}

export interface AdaTieredNetSplit {
  low_percent: number;
  high_percent: number;
  threshold_gross: number;
}

export interface AdaBonus {
  type: "sellout" | "gross_threshold" | "attendance_threshold";
  trigger: string;
  amount: number;
  stacks: boolean;
}

export interface ChangeFromPrevious {
  field_path: string;
  previous_value: unknown;
  new_value: unknown;
  evidence_quote: string;
}

export interface AdaExtraction {
  deal_type: AdaDealType;
  guarantee_amount: number | null;
  percentage: number | null;
  percentage_basis: "gross" | "net" | null;
  expense_cap: number | null;
  hospitality_cap: number | null;
  ratchet: AdaRatchet | null;
  walkout_pot: AdaWalkoutPot | null;
  tiered_net_split: AdaTieredNetSplit | null;
  bonuses: AdaBonus[];
  complex_structure: boolean;
  raw_text_preserved: string;
  changes_from_previous?: ChangeFromPrevious[] | null;
}

export interface AdaFlag {
  flag_class: AdaFlagClass;
  field_affected: AdaFieldAffected;
  description: string;
  evidence_quote: string | null;
  suggested_question: string | null;
}

export interface AdaApiRequest {
  deal_id: string;
  pasted_text: string;
  mode: AdaMode;
}

export interface AdaHistoryEntry {
  id: string;
  pastedText: string;
  modeUsed: AdaMode;
  pastedAt: string; // ISO string
  extractionSnapshotJson: string | null;
}

export interface AdaApiSuccess {
  extraction: AdaExtraction;
  flags: AdaFlag[];
  mode_used: AdaMode;
  history_id: string;
  priorHistory: AdaHistoryEntry[]; // 3 prior rows, excluding current run, most recent first
}

export interface AdaApiError {
  error: string;
  history_id: string;
}

export type AdaApiResponse = AdaApiSuccess | AdaApiError;

import type { AdaExtraction, AdaMode } from "./types";

const DEAL_TYPE_GUIDE = `
## Deal types and which fields apply

**flat** — Flat guarantee only. Artist receives a fixed dollar amount regardless of box office.
  Fields: guarantee_amount only. percentage, ratchet, walkout_pot, tiered_net_split are null.

**vs** (guarantee vs. percentage) — Artist receives the greater of a guarantee or a percentage of net/gross.
  Fields: guarantee_amount, percentage, percentage_basis. May also have ratchet, walkout_pot, tiered_net_split, bonuses.
  This is the most structurally complex deal type.

**percentage_of_net** — Artist receives a percentage of net box office (no guarantee, or guarantee vs. percentage whichever greater).
  Fields: percentage, percentage_basis (always "net"). May have expense_cap, hospitality_cap.

**percentage_of_gross** — Artist receives a percentage of gross box office. No expense deductions.
  Fields: percentage, percentage_basis (always "gross"). ratchet, walkout_pot are null.

**door** — Artist receives ticket revenue minus capped expenses.
  Fields: expense_cap (required), hospitality_cap (optional). guarantee_amount and percentage are null.
`.trim();

const AMBIGUITY_CLASS_GUIDE = `
## Ambiguity classes to detect

Generate a flag for each of the following when present in the email text. Do not force a flag when the class is clearly absent.

**ambiguous_net** — A vs or percentage-of-net deal where the email uses "net" without defining what is deducted from gross. No mention of expense deductions, ticket fees, etc. Example phrase: "85/15 net" with no qualifying language. Do NOT flag deals that explicitly say "net after expenses" or "gross."

**external_reference** — Deal references terms living in another document or communication, making those terms unverifiable from the email alone. Example phrase: "per the deal memo," "see email thread," "per our phone call," "bonuses per the email." Flag this when bonus amounts or deal terms are deferred to an outside source.

**computed_threshold** — A walkout pot or similar structure where the trigger threshold is described as a dollar amount that equals the breakeven (guarantee + projected expenses) rather than a contractual fixed amount. If actual expenses deviate, the stated threshold will be wrong at settlement. Example phrase: "walkout pot: 100% of gross above $3,200" where $3,200 appears to be a computed breakeven.

**missing_overage** — The deal specifies an expense cap or hospitality cap but says nothing about who absorbs costs if actual expenses exceed the cap. Example phrase: "Expense cap $1,950" with no "overages absorbed by venue" or similar language. Flag on any deal that has a cap with no overage language.

**unresolved_reference** — ONLY in update mode. The new email references context not present in the prior extraction record. Example phrase: "the +500 stays in" where no +500 was in the prior record.
`.trim();

export function buildSystemPrompt(): string {
  return `You are a deal-term extraction engine for a venue booking system used by independent music venues.

Your job: read a deal email between a venue booker and a booking agent, extract structured deal terms, and identify ambiguities that need human review before settlement.

${DEAL_TYPE_GUIDE}

${AMBIGUITY_CLASS_GUIDE}

## General extraction rules

- Identify the deal type first — it determines which fields are meaningful.
- For fields that don't apply to the deal type, output null.
- Normalize notation variants to the same structure. "85/15 net," "$X vs 85% of net after expenses," "$X g'tee vs 85/15 after expenses" all mean the same thing.
- Set complex_structure: true only when the deal genuinely doesn't fit the schema cleanly (e.g., a ratchet combined with a tiered net split combined with multiple stacked bonus tiers).
- Always copy the full original text verbatim into raw_text_preserved.
- For every flag you generate, include an evidence_quote: copy the exact phrase from the email that triggered the flag. If no specific phrase applies, set evidence_quote to null.
- The field_affected value should identify the specific deal field the flag relates to. Use "global" only for flags that span the entire deal (e.g., a bracketed override note, a mode-fallback advisory).
- For every flag you generate, produce a suggested_question: a single neutral sentence Mariana could send to the agent to resolve the ambiguity. The question must be specific to the evidence quoted, neutral in framing (do not imply a preferred answer), and short enough to paste directly into an email. Example for an ambiguous_net flag: "Could you confirm whether 'net' in this deal means gross box office minus approved venue expenses, or whether there are additional deductions (ticket fees, credit card surcharges, etc.) that come out first?"
- Generate zero flags if the deal is clear. Do not pad with unnecessary warnings.
- Percentages should be expressed as decimals (e.g., 85% → 0.85).`;
}

type HistoryRow = {
  modeUsed: AdaMode;
  pastedAt: Date | string;
  extractionSnapshotJson: string | null;
};

export function buildUserMessage(
  mode: AdaMode,
  pastedText: string,
  priorExtraction?: AdaExtraction | null,
  history?: HistoryRow[] | null,
): string {
  if (mode === "update" && priorExtraction) {
    const validHistory = (history ?? []).filter(
      (h): h is HistoryRow & { extractionSnapshotJson: string } =>
        h.extractionSnapshotJson != null,
    );

    let historySection = "";
    if (validHistory.length > 0) {
      const lines = validHistory.map((h, i) => {
        const ts =
          h.pastedAt instanceof Date
            ? h.pastedAt.toISOString()
            : h.pastedAt;
        return `Run ${i + 1} — [${h.modeUsed}, ${ts}]: ${h.extractionSnapshotJson}`;
      });
      historySection = `Prior run history for this deal (oldest to most recent):\n${lines.join("\n")}\n\n`;
    } else {
      historySection = `Prior extraction on file:\n${JSON.stringify(priorExtraction, null, 2)}\n\n`;
    }

    return `Mode: UPDATE

${historySection}New email text to process:
${pastedText}

Instructions for update mode:
1. Produce a full new extraction reflecting the current deal state (do not omit fields that haven't changed).
2. Populate changes_from_previous with an entry for each field that changed between the prior extraction and the new email. Include field_path, previous_value, new_value, and evidence_quote (exact phrase from the new email).
3. For fields unchanged, carry forward the prior values exactly.
4. If the new email references context not present in the prior extraction (e.g., "the +500 stays in" with no prior +500), generate an unresolved_reference flag.
5. Use the full run history above to understand how the deal has evolved — identify what the new email changes, contradicts, or adds relative to all prior versions.`;
  }

  return `Mode: ${mode.toUpperCase()}

Deal email text:
${pastedText}`;
}

