411	        <ul className="space-y-3">
412	          {changes.map((c, i) => (
413	            <li key={i} className="text-[12.5px] text-ink-800">
414	              <div className="font-mono text-[11px] text-ink-500 mb-0.5">{c.field_path}</div>
415	              <div className="flex items-center gap-2 flex-wrap">
416	                <span className="text-ink-500 line-through">{String(c.previous_value ?? "—")}</span>
417	                <ArrowRight className="h-3 w-3 text-ink-400 shrink-0" />
418	                <span className="font-medium text-ink-900">{String(c.new_value ?? "—")}</span>
419	              </div>
420	              {c.evidence_quote && (
421	                <blockquote className="mt-1 pl-2 border-l-2 border-sky-300 text-[11px] text-sky-700 italic">
422	                  &ldquo;{c.evidence_quote}&rdquo;
423	                </blockquote>
424	              )}
425	            </li>
426	          ))}
427	        </ul>
428	      </div>
429	    </div>
430	  );
431	}
432	
433	// ─── Extraction result display ───────────────────────────────────────────────
434	
435	function ExtractionResult({
436	  extraction,
437	  flags,
438	  modeUsed,
439	  priorRunText,
440	}: {
441	  extraction: AdaExtraction;
442	  flags: AdaFlag[];
443	  modeUsed: AdaMode;
444	  priorRunText?: string;
445	}) {
446	  const flagMap = new Map<AdaFieldAffected, AdaFlag[]>();
447	  for (const f of flags) {
448	    const existing = flagMap.get(f.field_affected) ?? [];
449	    flagMap.set(f.field_affected, [...existing, f]);
450	  }
451	
452	  const globalFlags = flagMap.get("global") ?? [];
453	
454	  return (
455	    <div className="space-y-4">
456	      {globalFlags.length > 0 && (
457	        <div className="space-y-2">
458	          {globalFlags.map((f, i) => <FlagItem key={i} flag={f} />)}
459	        </div>
460	      )}
461	
462	      {modeUsed === "update" && (
463	        <DeltaPanel
464	          extraction={extraction}
465	          currentRunText={extraction.raw_text_preserved || undefined}
466	          priorRunText={priorRunText}
467	        />
468	      )}
469	
470	      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
471	        <CoreTermsCard extraction={extraction} flagMap={flagMap} />
472	        <PercentageSplitCard extraction={extraction} flagMap={flagMap} />
473	        <CapsCard extraction={extraction} flagMap={flagMap} />
474	        <EscalatorsCard extraction={extraction} flagMap={flagMap} />
475	        <BonusesCard extraction={extraction} flagMap={flagMap} />
476	      </div>
477	
478	      {extraction.complex_structure && (
479	        <div className="flex items-center gap-2 text-[12px] text-ink-500 pt-1">
480	          <Info className="h-3.5 w-3.5" />
481	          Ada marked this deal as complex — it may not fit the standard schema cleanly. Review the original text.
482	        </div>
483	      )}
484	
485	    </div>
486	  );
487	}
488	
489	// ─── Prior runs accordion ────────────────────────────────────────────────────
490	
491	function PriorRunItem({ run }: { run: AdaHistoryEntry }) {
492	  const [expanded, setExpanded] = useState(false);
493	  const [showBreakdown, setShowBreakdown] = useState(false);
494	
495	  // Parse snapshot once; treat malformed JSON the same as null.
496	  let snapshotData: { extraction: AdaExtraction; flags: AdaFlag[] } | null = null;
497	  if (run.extractionSnapshotJson) {
498	    try {
499	      snapshotData = JSON.parse(run.extractionSnapshotJson);
500	    } catch {
501	      // malformed — falls through to failure state
502	    }
503	  }
504	  const hasSnapshot = snapshotData !== null;
505	
506	  return (
507	    <div className="rounded-lg ring-1 ring-ink-200/60 bg-white overflow-hidden">
508	      {/* Header row — click to expand/collapse */}
509	      <button
510	        type="button"
511	        onClick={() => setExpanded((v) => !v)}
512	        className="w-full flex items-start justify-between gap-3 px-4 py-3 text-left hover:bg-ink-50/40 transition-colors"
513	      >
514	        <div className="min-w-0 flex-1">
515	          <div className="flex items-center gap-2">
516	            <span className="text-[11px] text-ink-500">{formatTimestamp(run.pastedAt)}</span>
517	            <span className="text-ink-300">·</span>
518	            <span className="text-[11px] text-ink-500">{MODE_LABELS[run.modeUsed]}</span>
519	          </div>
520	        </div>
521	        {expanded
522	          ? <ChevronUp className="h-3.5 w-3.5 text-ink-400 shrink-0 mt-1" />
523	          : <ChevronDown className="h-3.5 w-3.5 text-ink-400 shrink-0 mt-1" />
524	        }
525	      </button>
526	
527	      {/* Expanded body */}
528	      {expanded && (
529	        <div className="px-4 pb-4 border-t border-ink-100/80">
530	          {/* Full submitted text */}
531	          <div className="mt-3">
532	            <div
533	              className="text-[12px] text-ink-700 bg-canvas-soft rounded-lg p-4 ring-1 ring-ink-200/50 leading-relaxed whitespace-pre-wrap font-[450]"
534	              style={{ fontStyle: "italic" }}
535	            >
536	              {run.pastedText}
537	            </div>
538	          </div>
539	
540	          {/* Extraction breakdown */}
541	          <div className="mt-3">
542	            {!run.extractionSnapshotJson || !hasSnapshot ? (
543	              <p className="text-[12px] text-ink-400 italic">
544	                Extraction failed — input preserved
545	              </p>
546	            ) : (
547	              <>
548	                <button
549	                  type="button"
550	                  onClick={() => setShowBreakdown((v) => !v)}
551	                  className="flex items-center gap-1.5 text-[11.5px] text-ink-400 hover:text-ink-700 transition-colors"
552	                >
553	                  {showBreakdown
554	                    ? <ChevronUp className="h-3.5 w-3.5" />
555	                    : <ChevronDown className="h-3.5 w-3.5" />
556	                  }
557	                  {showBreakdown ? "Hide" : "View"} extraction breakdown
558	                </button>
559	                {showBreakdown && (
560	                  <div className="mt-4">
561	                    <ExtractionResult
562	                      extraction={snapshotData!.extraction}
563	                      flags={snapshotData!.flags}
564	                      modeUsed={run.modeUsed}
565	                    />
566	                  </div>
567	                )}
568	              </>
569	            )}
570	          </div>
571	        </div>
572	      )}
573	    </div>
574	  );
575	}
576	
577	function PriorRunsAccordion({ runs }: { runs: AdaHistoryEntry[] }) {
578	  const [open, setOpen] = useState(false);
579	
580	  if (runs.length === 0) return null;
581	
582	  return (
583	    <div className="mt-4">
584	      <button
585	        type="button"
586	        onClick={() => setOpen((v) => !v)}
587	        className="flex items-center gap-1.5 text-[12px] text-ink-500 hover:text-ink-800 transition-colors"
588	      >
589	        {open
590	          ? <ChevronUp className="h-3.5 w-3.5" />
591	          : <ChevronDown className="h-3.5 w-3.5" />
592	        }
593	        Previous runs ({runs.length})
594	      </button>
595	
596	      {open && (
597	        <div className="mt-3 space-y-2">
598	          {runs.map((run) => (
599	            <PriorRunItem key={run.id} run={run} />
600	          ))}
601	        </div>
602	      )}
603	    </div>
604	  );
605	}
606	
607	// ─── Main component ──────────────────────────────────────────────────────────
608	
609	export function AdaSection({
610	  dealId,
611	  dealNotesFreetext,
612	  existingExtraction,
613	  existingFlags,
614	  existingHistory,
615	}: {
616	  dealId: string;
617	  dealNotesFreetext: string | null;
618	  existingExtraction: AdaExtraction | null;
619	  existingFlags: AdaFlag[] | null;
620	  existingHistory: AdaHistoryEntry[]; // all rows for this deal, DESC by pastedAt, limit 4
621	}) {
622	  const router = useRouter();
623	
624	  const [pastedText, setPastedText] = useState("");
625	  const [mode, setMode] = useState<AdaMode>(existingExtraction != null ? "update" : "initial");
626	  const [isLoading, setIsLoading] = useState(false);
627	  const [loadingPhase, setLoadingPhase] = useState(0);
628	  const [result, setResult] = useState<AdaApiSuccess | null>(null);
629	  const [error, setError] = useState<string | null>(null);
630	  // existingHistory[0] is the most-recent (= current) row; slice(1) gives prior runs.
631	  const [priorRuns, setPriorRuns] = useState<AdaHistoryEntry[]>(existingHistory.slice(1));
632	
633	  const loadingIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
634	
635	  useEffect(() => {
636	    if (isLoading) {
637	      setLoadingPhase(0);
638	      loadingIntervalRef.current = setInterval(() => {
639	        setLoadingPhase((p) => (p + 1) % LOADING_MESSAGES.length);
640	      }, 2000);
641	    } else {
642	      if (loadingIntervalRef.current) {
643	        clearInterval(loadingIntervalRef.current);
644	        loadingIntervalRef.current = null;
645	      }
646	    }
647	    return () => {
648	      if (loadingIntervalRef.current) clearInterval(loadingIntervalRef.current);
649	    };
650	  }, [isLoading]);
651	
652	  // A prior extraction exists either from the server or from this session.
653	  const hasExisting = existingExtraction != null || result != null;
654	
655	  const displayExtraction = result?.extraction ?? existingExtraction ?? null;
656	  const displayFlags = result?.flags ?? existingFlags ?? null;
657	  const displayMode = result?.mode_used ?? (existingExtraction != null ? "update" : "initial");
658	
659	  // True when the most-recent persisted run failed and nothing has succeeded yet this session.
660	  const lastRunFailed =
661	    result === null &&
662	    existingHistory.length > 0 &&
663	    existingHistory[0].extractionSnapshotJson === null;
664	
665	  async function handleSubmit(e: React.FormEvent) {
666	    e.preventDefault();
667	    if (!pastedText.trim() || isLoading) return;
668	
669	    setIsLoading(true);
670	    setError(null);
671	
672	    try {
673	      const res = await fetch("/api/ada/extract", {
674	        method: "POST",
675	        headers: { "Content-Type": "application/json" },
676	        body: JSON.stringify({
677	          deal_id: dealId,
678	          pasted_text: pastedText,
679	          mode,
680	        }),
681	      });
682	
683	      const data = await res.json();
684	
685	      if (!res.ok || "error" in data) {
686	        setError(data.error ?? "Something went wrong. Please try again.");
687	      } else {
688	        const success = data as AdaApiSuccess;
689	        setResult(success);
690	        setPastedText("");
691	        setMode("update");
692	        setPriorRuns(success.priorHistory);
693	        router.refresh();
694	      }
695	    } catch {
696	      setError("Network error. Your input has been saved if it reached the server.");
697	    } finally {
698	      setIsLoading(false);
699	    }
700	  }
701	
702	  return (
703	    <div className="mt-8">
704	      <div className="flex items-center gap-2 mb-4">
705	        <Sparkles className="h-4 w-4 text-brand-600" />
706	        <h2 className="text-[13px] font-semibold text-ink-900 tracking-tight">Ask Ada</h2>
707	        <span className="text-[11px] text-ink-400">· Deal disambiguation assistant</span>
708	      </div>
709	
710	      {/* 1. Current extraction results */}
711	      {displayExtraction && displayFlags && (
712	        <div className="mb-6">
713	          <ExtractionResult
714	            extraction={displayExtraction}
715	            flags={displayFlags}
716	            modeUsed={displayMode as AdaMode}
717	            priorRunText={priorRuns[0]?.pastedText}
718	          />
719	        </div>
720	      )}
721	
722	      {/* 2. Ask Ada container */}
723	      <Card>
724	        <CardContent className="pt-5">
725	          <form onSubmit={handleSubmit} className="space-y-4">
726	            {lastRunFailed && (
727	              <div className="rounded-md ring-1 ring-amber-200/70 bg-amber-50/60 px-4 py-3 flex items-start gap-2">
728	                <AlertTriangle className="h-3.5 w-3.5 text-amber-600 shrink-0 mt-0.5" />
729	                <p className="text-[12px] text-amber-800">
730	                  Last Ada run failed — your input was preserved. Run Ada again to retry.
731	                </p>
732	              </div>
733	            )}
734	            <div>
735	              <div className="flex items-baseline justify-between mb-2">
736	                <label
737	                  htmlFor="ada-paste"
738	                  className="eyebrow text-[10px] text-ink-500"
739	                >
740	                  Paste the latest deal email or agent communication
741	                </label>
742	                {dealNotesFreetext && (
743	                  <button
744	                    type="button"
745	                    onClick={() => setPastedText(dealNotesFreetext)}
746	                    className="text-[11px] text-brand-600 hover:text-brand-800 transition-colors"
747	                  >
748	                    ↓ Insert current deal notes
749	                  </button>
750	                )}
751	              </div>
752	              <textarea
753	                id="ada-paste"
754	                value={pastedText}
755	                onChange={(e) => setPastedText(e.target.value)}
756	                placeholder="Paste deal email here..."
757	                rows={6}
758	                className="w-full rounded-md ring-1 ring-ink-200/80 bg-canvas-soft px-4 py-3 text-[13px] text-ink-900 placeholder:text-ink-300 resize-y focus:outline-none focus:ring-2 focus:ring-brand-400/60 leading-relaxed"
759	                disabled={isLoading}
760	              />
761	            </div>
762	
763	            {/* Mode selector — shown once a prior extraction exists */}
764	            {hasExisting && (
765	              <div className="flex items-center gap-4">
766	                <span className="eyebrow text-[10px] text-ink-500">Mode</span>
767	                {(["update", "replace"] as const).map((m) => (
768	                  <label
769	                    key={m}
770	                    className={cn(
771	                      "flex items-center gap-1.5 text-[12.5px] cursor-pointer",
772	                      mode === m ? "text-ink-900" : "text-ink-500",
773	                      isLoading && "opacity-50 pointer-events-none",
774	                    )}
775	                  >
776	                    <input
777	                      type="radio"
778	                      name="ada-mode"
779	                      value={m}
780	                      checked={mode === m}
781	                      onChange={() => setMode(m)}
782	                      className="accent-brand-600"
783	                      disabled={isLoading}
784	                    />
785	                    <span className="capitalize">{m}</span>
786	                  </label>
787	                ))}
788	              </div>
789	            )}
790	
791	            {error && (
792	              <div className="rounded-md ring-1 ring-rose-200 bg-rose-50/60 px-4 py-3 text-[12.5px] text-rose-800">
793	                {error}
794	              </div>
795	            )}
796	
797	            <Button
798	              type="submit"
799	              variant="brand"
800	              disabled={!pastedText.trim() || isLoading}
801	            >
802	              {isLoading ? (
803	                <span className="flex items-center gap-2">
804	                  <span className="inline-block h-3.5 w-3.5 rounded-full border-2 border-white/30 border-t-white animate-spin" />
805	                  {LOADING_MESSAGES[loadingPhase]}
806	                </span>
807	              ) : (
808	                <>
809	                  <Sparkles className="h-3.5 w-3.5" />
810	                  Ask Ada
811	                </>
812	              )}
813	            </Button>
814	          </form>
815	        </CardContent>
816	      </Card>
817	
818	      {/* 3. Prior runs accordion */}
819	      <PriorRunsAccordion runs={priorRuns} />
820	    </div>
821	  );
822	}
