"use client";

import { useState, useEffect, useRef } from "react";
import { useRouter } from "next/navigation";
import { Sparkles, ChevronDown, ChevronUp, AlertTriangle, Info, ArrowRight, Copy, Check } from "lucide-react";
import {
  Card,
  CardHeader,
  CardTitle,
  CardContent,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import type {
  AdaExtraction,
  AdaFlag,
  AdaFieldAffected,
  AdaMode,
  AdaApiSuccess,
  AdaHistoryEntry,
} from "@/lib/ada/types";

// ─── Helpers ────────────────────────────────────────────────────────────────

const LOADING_MESSAGES = [
  "Reading the email...",
  "Identifying deal terms...",
  "Checking for ambiguities...",
];

const FLAG_CLASS_LABELS: Record<AdaFlag["flag_class"], string> = {
  ambiguous_net: "Ambiguous net definition",
  external_reference: "Terms in external document",
  computed_threshold: "Computed threshold",
  missing_overage: "Overage responsibility unspecified",
  unresolved_reference: "Unresolved reference",
  bracketed_update: "Bracketed update detected",
  mode_fallback: "Mode adjusted",
  other: "Advisory",
};

const MODE_LABELS: Record<AdaMode, string> = {
  initial: "Initial",
  update: "Update",
  replace: "Replace",
};

function formatMoney(n: number | null | undefined): string {
  if (n == null) return "—";
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(n);
}

function formatPct(n: number | null | undefined): string {
  if (n == null) return "—";
  return `${(n * 100).toFixed(0)}%`;
}

function formatTimestamp(iso: string): string {
  return new Date(iso).toLocaleString("en-US", {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  });
}

// ─── Flag display ────────────────────────────────────────────────────────────

function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);

  function handleCopy() {
    navigator.clipboard.writeText(text).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    });
  }

  return (
    <button
      type="button"
      onClick={handleCopy}
      className="flex items-center gap-1 text-[10.5px] text-ink-400 hover:text-ink-700 transition-colors shrink-0"
      aria-label="Copy question"
    >
      {copied ? (
        <>
          <Check className="h-3 w-3 text-brand-600" />
          <span className="text-brand-600">Copied!</span>
        </>
      ) : (
        <>
          <Copy className="h-3 w-3" />
          <span>Copy</span>
        </>
      )}
    </button>
  );
}

function FlagItem({ flag, inline = false }: { flag: AdaFlag; inline?: boolean }) {
  return (
    <div
      className={cn(
        "rounded-md ring-1 ring-amber-200/70 bg-amber-50/60",
        inline ? "px-3 py-2 mt-2" : "px-4 py-3",
      )}
    >
      <div className="flex items-start gap-2">
        <AlertTriangle
          className={cn(
            "shrink-0 text-amber-600",
            inline ? "h-3 w-3 mt-0.5" : "h-3.5 w-3.5 mt-0.5",
          )}
        />
        <div className="min-w-0 w-full">
          <span
            className={cn(
              "font-medium text-amber-900",
              inline ? "text-[11px]" : "text-[12px]",
            )}
          >
            {FLAG_CLASS_LABELS[flag.flag_class]}
          </span>
          <p
            className={cn(
              "text-amber-800 mt-0.5 leading-relaxed",
              inline ? "text-[11px]" : "text-[12px]",
            )}
          >
            {flag.description}
          </p>
          {flag.evidence_quote && (
            <blockquote
              className={cn(
                "mt-1.5 pl-2 border-l-2 border-amber-300 text-amber-700 italic",
                inline ? "text-[10.5px]" : "text-[11px]",
              )}
            >
              &ldquo;{flag.evidence_quote}&rdquo;
            </blockquote>
          )}
          {flag.suggested_question && (
            <div className="mt-2 pt-2 border-t border-amber-200/60">
              <div className="flex items-start justify-between gap-2">
                <div className="min-w-0">
                  <div className="eyebrow text-[9px] text-amber-700 mb-1">Suggested question</div>
                  <p className={cn("text-amber-800 leading-relaxed", inline ? "text-[11px]" : "text-[12px]")}>
                    {flag.suggested_question}
                  </p>
                </div>
                <CopyButton text={flag.suggested_question} />
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// ─── Individual extraction cards ─────────────────────────────────────────────

function FieldRow({
  label,
  value,
  flags,
}: {
  label: string;
  value: React.ReactNode;
  flags?: AdaFlag[];
}) {
  return (
    <div>
      <div className="eyebrow text-[10px] text-ink-500 mb-1">{label}</div>
      <div className="text-[13.5px] text-ink-900 font-mono tabular">{value}</div>
      {flags?.map((f, i) => <FlagItem key={i} flag={f} inline />)}
    </div>
  );
}

function CoreTermsCard({
  extraction,
  flagMap,
}: {
  extraction: AdaExtraction;
  flagMap: Map<AdaFieldAffected, AdaFlag[]>;
}) {
  if (extraction.guarantee_amount == null) return null;
  return (
    <Card>
      <CardHeader>
        <CardTitle>Core terms</CardTitle>
      </CardHeader>
      <CardContent>
        <FieldRow
          label="Guarantee"
          value={formatMoney(extraction.guarantee_amount)}
          flags={flagMap.get("guarantee_amount")}
        />
      </CardContent>
    </Card>
  );
}

function PercentageSplitCard({
  extraction,
  flagMap,
}: {
  extraction: AdaExtraction;
  flagMap: Map<AdaFieldAffected, AdaFlag[]>;
}) {
  if (extraction.percentage == null && extraction.percentage_basis == null) return null;
  return (
    <Card>
      <CardHeader>
        <CardTitle>Percentage split</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <FieldRow
          label="Percentage"
          value={formatPct(extraction.percentage)}
          flags={flagMap.get("percentage")}
        />
        <FieldRow
          label="Basis"
          value={
            extraction.percentage_basis ? (
              <span className="capitalize">{extraction.percentage_basis}</span>
            ) : (
              "—"
            )
          }
          flags={flagMap.get("percentage_basis")}
        />
      </CardContent>
    </Card>
  );
}

function CapsCard({
  extraction,
  flagMap,
}: {
  extraction: AdaExtraction;
  flagMap: Map<AdaFieldAffected, AdaFlag[]>;
}) {
  if (extraction.expense_cap == null && extraction.hospitality_cap == null) return null;
  return (
    <Card>
      <CardHeader>
        <CardTitle>Caps</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {extraction.expense_cap != null && (
          <FieldRow
            label="Expense cap"
            value={formatMoney(extraction.expense_cap)}
            flags={flagMap.get("expense_cap")}
          />
        )}
        {extraction.hospitality_cap != null && (
          <FieldRow
            label="Hospitality cap"
            value={formatMoney(extraction.hospitality_cap)}
            flags={flagMap.get("hospitality_cap")}
          />
        )}
      </CardContent>
    </Card>
  );
}

function EscalatorsCard({
  extraction,
  flagMap,
}: {
  extraction: AdaExtraction;
  flagMap: Map<AdaFieldAffected, AdaFlag[]>;
}) {
  const hasAny =
    extraction.ratchet != null ||
    extraction.walkout_pot != null ||
    extraction.tiered_net_split != null;
  if (!hasAny) return null;

  return (
    <Card>
      <CardHeader>
        <CardTitle>Escalators</CardTitle>
      </CardHeader>
      <CardContent className="space-y-5">
        {extraction.ratchet && (
          <div>
            <div className="eyebrow text-[10px] text-ink-500 mb-2">Ratchet</div>
            <div className="text-[13px] text-ink-800 leading-relaxed">
              {formatPct(extraction.ratchet.base_percent)} base →{" "}
              {formatPct(extraction.ratchet.cap_percent)} above{" "}
              {formatPct(extraction.ratchet.trigger_capacity_pct)} capacity
            </div>
            {flagMap.get("ratchet")?.map((f, i) => <FlagItem key={i} flag={f} inline />)}
          </div>
        )}
        {extraction.walkout_pot && (
          <div>
            <div className="eyebrow text-[10px] text-ink-500 mb-2">Walkout pot</div>
            <div className="text-[13px] text-ink-800 leading-relaxed">
              100% of gross above {formatMoney(extraction.walkout_pot.threshold_amount)}
              {extraction.walkout_pot.threshold_source === "computed" && (
                <span className="ml-1.5 text-[11px] text-ink-400">(computed threshold)</span>
              )}
            </div>
            {flagMap.get("walkout_pot")?.map((f, i) => <FlagItem key={i} flag={f} inline />)}
          </div>
        )}
        {extraction.tiered_net_split && (
          <div>
            <div className="eyebrow text-[10px] text-ink-500 mb-2">Tiered net split</div>
            <div className="text-[13px] text-ink-800 leading-relaxed">
              {formatPct(extraction.tiered_net_split.low_percent)} up to{" "}
              {formatMoney(extraction.tiered_net_split.threshold_gross)} gross, then{" "}
              {formatPct(extraction.tiered_net_split.high_percent)}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

function BonusesCard({
  extraction,
  flagMap,
}: {
  extraction: AdaExtraction;
  flagMap: Map<AdaFieldAffected, AdaFlag[]>;
}) {
  if (!extraction.bonuses || extraction.bonuses.length === 0) return null;

  return (
    <Card>
      <CardHeader>
        <CardTitle>Bonuses</CardTitle>
      </CardHeader>
      <CardContent>
        <ul className="space-y-3">
          {extraction.bonuses.map((b, i) => (
            <li key={i} className="text-[13px] text-ink-800 leading-relaxed">
              <span className="inline-flex items-center px-1.5 py-px rounded text-[9px] font-mono uppercase tracking-wider bg-white ring-1 ring-brand-200/50 text-brand-800 mr-2">
                {b.type === "gross_threshold"
                  ? "gross"
                  : b.type === "attendance_threshold"
                    ? "attend"
                    : "sellout"}
              </span>
              {b.trigger}
              {" · "}
              <span className="font-mono tabular">{formatMoney(b.amount)}</span>
              {b.stacks && (
                <span className="ml-1.5 text-[11px] text-ink-400">stacks</span>
              )}
            </li>
          ))}
        </ul>
        {flagMap.get("bonuses")?.map((f, i) => <FlagItem key={i} flag={f} inline />)}
      </CardContent>
    </Card>
  );
}

// ─── Delta panel (Update mode) ───────────────────────────────────────────────

function DeltaPanel({
  extraction,
  currentRunText,
  priorRunText,
}: {
  extraction: AdaExtraction;
  currentRunText?: string;
  priorRunText?: string;
}) {
  const changes = extraction.changes_from_previous;
  if (!changes || changes.length === 0) return null;

  return (
    <div className="rounded-lg ring-1 ring-sky-200/70 bg-sky-50/50 px-5 py-4 space-y-4">
      {currentRunText && (
        <div>
          <div className="eyebrow text-[9px] text-sky-600 mb-1.5">Current run</div>
          <blockquote className="pl-3 border-l-2 border-sky-300 text-[11.5px] text-sky-900 italic leading-relaxed whitespace-pre-wrap">
            {currentRunText}
          </blockquote>
        </div>
      )}
      {priorRunText && (
        <div>
          <div className="eyebrow text-[9px] text-sky-500 mb-1.5">Previous run</div>
          <blockquote className="pl-3 border-l-2 border-sky-200 text-[11.5px] text-sky-700/60 italic leading-relaxed whitespace-pre-wrap">
            {priorRunText}
          </blockquote>
        </div>
      )}
      <div>
        <div className="eyebrow text-[10px] text-sky-700 mb-3">Changes from prior version</div>
        <ul className="space-y-3">
          {changes.map((c, i) => (
            <li key={i} className="text-[12.5px] text-ink-800">
              <div className="font-mono text-[11px] text-ink-500 mb-0.5">{c.field_path}</div>
              <div className="flex items-center gap-2 flex-wrap">
                <span className="text-ink-500 line-through">{String(c.previous_value ?? "—")}</span>
                <ArrowRight className="h-3 w-3 text-ink-400 shrink-0" />
                <span className="font-medium text-ink-900">{String(c.new_value ?? "—")}</span>
              </div>
              {c.evidence_quote && (
                <blockquote className="mt-1 pl-2 border-l-2 border-sky-300 text-[11px] text-sky-700 italic">
                  &ldquo;{c.evidence_quote}&rdquo;
                </blockquote>
              )}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

// ─── Extraction result display ───────────────────────────────────────────────

function ExtractionResult({
  extraction,
  flags,
  modeUsed,
  priorRunText,
}: {
  extraction: AdaExtraction;
  flags: AdaFlag[];
  modeUsed: AdaMode;
  priorRunText?: string;
}) {
  const flagMap = new Map<AdaFieldAffected, AdaFlag[]>();
  for (const f of flags) {
    const existing = flagMap.get(f.field_affected) ?? [];
    flagMap.set(f.field_affected, [...existing, f]);
  }

  const globalFlags = flagMap.get("global") ?? [];

  return (
    <div className="space-y-4">
      {globalFlags.length > 0 && (
        <div className="space-y-2">
          {globalFlags.map((f, i) => <FlagItem key={i} flag={f} />)}
        </div>
      )}

      {modeUsed === "update" && (
        <DeltaPanel
          extraction={extraction}
          currentRunText={extraction.raw_text_preserved || undefined}
          priorRunText={priorRunText}
        />
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <CoreTermsCard extraction={extraction} flagMap={flagMap} />
        <PercentageSplitCard extraction={extraction} flagMap={flagMap} />
        <CapsCard extraction={extraction} flagMap={flagMap} />
        <EscalatorsCard extraction={extraction} flagMap={flagMap} />
        <BonusesCard extraction={extraction} flagMap={flagMap} />
      </div>

      {extraction.complex_structure && (
        <div className="flex items-center gap-2 text-[12px] text-ink-500 pt-1">
          <Info className="h-3.5 w-3.5" />
          Ada marked this deal as complex — it may not fit the standard schema cleanly. Review the original text.
        </div>
      )}

    </div>
  );
}

// ─── Prior runs accordion ────────────────────────────────────────────────────

function PriorRunItem({ run }: { run: AdaHistoryEntry }) {
  const [expanded, setExpanded] = useState(false);
  const [showBreakdown, setShowBreakdown] = useState(false);

  // Parse snapshot once; treat malformed JSON the same as null.
  let snapshotData: { extraction: AdaExtraction; flags: AdaFlag[] } | null = null;
  if (run.extractionSnapshotJson) {
    try {
      snapshotData = JSON.parse(run.extractionSnapshotJson);
    } catch {
      // malformed — falls through to failure state
    }
  }
  const hasSnapshot = snapshotData !== null;

  return (
    <div className="rounded-lg ring-1 ring-ink-200/60 bg-white overflow-hidden">
      {/* Header row — click to expand/collapse */}
      <button
        type="button"
        onClick={() => setExpanded((v) => !v)}
        className="w-full flex items-start justify-between gap-3 px-4 py-3 text-left hover:bg-ink-50/40 transition-colors"
      >
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <span className="text-[11px] text-ink-500">{formatTimestamp(run.pastedAt)}</span>
            <span className="text-ink-300">·</span>
            <span className="text-[11px] text-ink-500">{MODE_LABELS[run.modeUsed]}</span>
          </div>
        </div>
        {expanded
          ? <ChevronUp className="h-3.5 w-3.5 text-ink-400 shrink-0 mt-1" />
          : <ChevronDown className="h-3.5 w-3.5 text-ink-400 shrink-0 mt-1" />
        }
      </button>

      {/* Expanded body */}
      {expanded && (
        <div className="px-4 pb-4 border-t border-ink-100/80">
          {/* Full submitted text */}
          <div className="mt-3">
            <div
              className="text-[12px] text-ink-700 bg-canvas-soft rounded-lg p-4 ring-1 ring-ink-200/50 leading-relaxed whitespace-pre-wrap font-[450]"
              style={{ fontStyle: "italic" }}
            >
              {run.pastedText}
            </div>
          </div>

          {/* Extraction breakdown */}
          <div className="mt-3">
            {!run.extractionSnapshotJson || !hasSnapshot ? (
              <p className="text-[12px] text-ink-400 italic">
                Extraction failed — input preserved
              </p>
            ) : (
              <>
                <button
                  type="button"
                  onClick={() => setShowBreakdown((v) => !v)}
                  className="flex items-center gap-1.5 text-[11.5px] text-ink-400 hover:text-ink-700 transition-colors"
                >
                  {showBreakdown
                    ? <ChevronUp className="h-3.5 w-3.5" />
                    : <ChevronDown className="h-3.5 w-3.5" />
                  }
                  {showBreakdown ? "Hide" : "View"} extraction breakdown
                </button>
                {showBreakdown && (
                  <div className="mt-4">
                    <ExtractionResult
                      extraction={snapshotData!.extraction}
                      flags={snapshotData!.flags}
                      modeUsed={run.modeUsed}
                    />
                  </div>
                )}
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

function PriorRunsAccordion({ runs }: { runs: AdaHistoryEntry[] }) {
  const [open, setOpen] = useState(false);

  if (runs.length === 0) return null;

  return (
    <div className="mt-4">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="flex items-center gap-1.5 text-[12px] text-ink-500 hover:text-ink-800 transition-colors"
      >
        {open
          ? <ChevronUp className="h-3.5 w-3.5" />
          : <ChevronDown className="h-3.5 w-3.5" />
        }
        Previous runs ({runs.length})
      </button>

      {open && (
        <div className="mt-3 space-y-2">
          {runs.map((run) => (
            <PriorRunItem key={run.id} run={run} />
          ))}
        </div>
      )}
    </div>
  );
}

// ─── Main component ──────────────────────────────────────────────────────────

export function AdaSection({
  dealId,
  dealNotesFreetext,
  existingExtraction,
  existingFlags,
  existingHistory,
}: {
  dealId: string;
  dealNotesFreetext: string | null;
  existingExtraction: AdaExtraction | null;
  existingFlags: AdaFlag[] | null;
  existingHistory: AdaHistoryEntry[]; // all rows for this deal, DESC by pastedAt, limit 4
}) {
  const router = useRouter();

  const [pastedText, setPastedText] = useState("");
  const [mode, setMode] = useState<AdaMode>(existingExtraction != null ? "update" : "initial");
  const [isLoading, setIsLoading] = useState(false);
  const [loadingPhase, setLoadingPhase] = useState(0);
  const [result, setResult] = useState<AdaApiSuccess | null>(null);
  const [error, setError] = useState<string | null>(null);
  // existingHistory[0] is the most-recent (= current) row; slice(1) gives prior runs.
  const [priorRuns, setPriorRuns] = useState<AdaHistoryEntry[]>(existingHistory.slice(1));

  const loadingIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (isLoading) {
      setLoadingPhase(0);
      loadingIntervalRef.current = setInterval(() => {
        setLoadingPhase((p) => (p + 1) % LOADING_MESSAGES.length);
      }, 2000);
    } else {
      if (loadingIntervalRef.current) {
        clearInterval(loadingIntervalRef.current);
        loadingIntervalRef.current = null;
      }
    }
    return () => {
      if (loadingIntervalRef.current) clearInterval(loadingIntervalRef.current);
    };
  }, [isLoading]);

  // A prior extraction exists either from the server or from this session.
  const hasExisting = existingExtraction != null || result != null;

  const displayExtraction = result?.extraction ?? existingExtraction ?? null;
  const displayFlags = result?.flags ?? existingFlags ?? null;
  const displayMode = result?.mode_used ?? (existingExtraction != null ? "update" : "initial");

  // True when the most-recent persisted run failed and nothing has succeeded yet this session.
  const lastRunFailed =
    result === null &&
    existingHistory.length > 0 &&
    existingHistory[0].extractionSnapshotJson === null;

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!pastedText.trim() || isLoading) return;

    setIsLoading(true);
    setError(null);

    try {
      const res = await fetch("/api/ada/extract", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          deal_id: dealId,
          pasted_text: pastedText,
          mode,
        }),
      });

      const data = await res.json();

      if (!res.ok || "error" in data) {
        setError(data.error ?? "Something went wrong. Please try again.");
      } else {
        const success = data as AdaApiSuccess;
        setResult(success);
        setPastedText("");
        setMode("update");
        setPriorRuns(success.priorHistory);
        router.refresh();
      }
    } catch {
      setError("Network error. Your input has been saved if it reached the server.");
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <div className="mt-8">
      <div className="flex items-center gap-2 mb-4">
        <Sparkles className="h-4 w-4 text-brand-600" />
        <h2 className="text-[13px] font-semibold text-ink-900 tracking-tight">Ask Ada</h2>
        <span className="text-[11px] text-ink-400">· Deal disambiguation assistant</span>
      </div>

      {/* 1. Current extraction results */}
      {displayExtraction && displayFlags && (
        <div className="mb-6">
          <ExtractionResult
            extraction={displayExtraction}
            flags={displayFlags}
            modeUsed={displayMode as AdaMode}
            priorRunText={priorRuns[0]?.pastedText}
          />
        </div>
      )}

      {/* 2. Ask Ada container */}
      <Card>
        <CardContent className="pt-5">
          <form onSubmit={handleSubmit} className="space-y-4">
            {lastRunFailed && (
              <div className="rounded-md ring-1 ring-amber-200/70 bg-amber-50/60 px-4 py-3 flex items-start gap-2">
                <AlertTriangle className="h-3.5 w-3.5 text-amber-600 shrink-0 mt-0.5" />
                <p className="text-[12px] text-amber-800">
                  Last Ada run failed — your input was preserved. Run Ada again to retry.
                </p>
              </div>
            )}
            <div>
              <div className="flex items-baseline justify-between mb-2">
                <label
                  htmlFor="ada-paste"
                  className="eyebrow text-[10px] text-ink-500"
                >
                  Paste the latest deal email or agent communication
                </label>
                {dealNotesFreetext && (
                  <button
                    type="button"
                    onClick={() => setPastedText(dealNotesFreetext)}
                    className="text-[11px] text-brand-600 hover:text-brand-800 transition-colors"
                  >
                    ↓ Insert current deal notes
                  </button>
                )}
              </div>
              <textarea
                id="ada-paste"
                value={pastedText}
                onChange={(e) => setPastedText(e.target.value)}
                placeholder="Paste deal email here..."
                rows={6}
                className="w-full rounded-md ring-1 ring-ink-200/80 bg-canvas-soft px-4 py-3 text-[13px] text-ink-900 placeholder:text-ink-300 resize-y focus:outline-none focus:ring-2 focus:ring-brand-400/60 leading-relaxed"
                disabled={isLoading}
              />
            </div>

            {/* Mode selector — shown once a prior extraction exists */}
            {hasExisting && (
              <div className="flex items-center gap-4">
                <span className="eyebrow text-[10px] text-ink-500">Mode</span>
                {(["update", "replace"] as const).map((m) => (
                  <label
                    key={m}
                    className={cn(
                      "flex items-center gap-1.5 text-[12.5px] cursor-pointer",
                      mode === m ? "text-ink-900" : "text-ink-500",
                      isLoading && "opacity-50 pointer-events-none",
                    )}
                  >
                    <input
                      type="radio"
                      name="ada-mode"
                      value={m}
                      checked={mode === m}
                      onChange={() => setMode(m)}
                      className="accent-brand-600"
                      disabled={isLoading}
                    />
                    <span className="capitalize">{m}</span>
                  </label>
                ))}
              </div>
            )}

            {error && (
              <div className="rounded-md ring-1 ring-rose-200 bg-rose-50/60 px-4 py-3 text-[12.5px] text-rose-800">
                {error}
              </div>
            )}

            <Button
              type="submit"
              variant="brand"
              disabled={!pastedText.trim() || isLoading}
            >
              {isLoading ? (
                <span className="flex items-center gap-2">
                  <span className="inline-block h-3.5 w-3.5 rounded-full border-2 border-white/30 border-t-white animate-spin" />
                  {LOADING_MESSAGES[loadingPhase]}
                </span>
              ) : (
                <>
                  <Sparkles className="h-3.5 w-3.5" />
                  Ask Ada
                </>
              )}
            </Button>
          </form>
        </CardContent>
      </Card>

      {/* 3. Prior runs accordion */}
      <PriorRunsAccordion runs={priorRuns} />
    </div>
  );
}

/**
 * Greenroom database schema.
 *
 * The data model is deliberately simple but realistic enough to support
 * the settlement workflows. Mariana (the booker at The Crescent) is the
 * primary user. Other personas (tour managers, agents, the GM) appear
 * in the data but don't have UI here.
 */

import { sqliteTable, text, integer, real } from "drizzle-orm/sqlite-core";

// -------- Users (operator accounts at the venue) --------

export const users = sqliteTable("users", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  role: text("role", {
    enum: ["booker", "gm", "production", "box_office"],
  }).notNull(),
  venueId: text("venue_id").notNull(),
});

// -------- Venues --------

export const venues = sqliteTable("venues", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  capacity: integer("capacity").notNull(),
  city: text("city").notNull(),
  state: text("state").notNull(),
});

// -------- Agencies & Agents --------

export const agencies = sqliteTable("agencies", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
});

export const agents = sqliteTable("agents", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  agencyId: text("agency_id").references(() => agencies.id),
  email: text("email").notNull(),
  phone: text("phone"),
  preferencesNotes: text("preferences_notes"),
});

// -------- Artists --------

export const artists = sqliteTable("artists", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  agentId: text("agent_id").references(() => agents.id),
  managerEmail: text("manager_email"),
  genre: text("genre"),
  priorShowCount: integer("prior_show_count").notNull().default(0),
});

// -------- Shows --------

export const shows = sqliteTable("shows", {
  id: text("id").primaryKey(),
  venueId: text("venue_id")
    .notNull()
    .references(() => venues.id),
  artistId: text("artist_id")
    .notNull()
    .references(() => artists.id),
  date: text("date").notNull(),
  status: text("status", {
    enum: ["booked", "advanced", "day_of", "settled", "closed"],
  })
    .notNull()
    .default("booked"),
  doorsTime: text("doors_time"),
  setTime: text("set_time"),
  openerArtistId: text("opener_artist_id").references(() => artists.id),
  roomConfig: text("room_config", { enum: ["standing", "seated", "mixed"] })
    .notNull()
    .default("standing"),
  internalNotes: text("internal_notes"),
  createdAt: integer("created_at", { mode: "timestamp" }).notNull(),
});

// -------- Deals --------

/**
 * One deal per show. The structure here is deliberately split:
 *
 *  - `dealType` and the structured fields (guarantee, percentage, etc.)
 *    are what the in-app settlement tool reads.
 *  - `dealNotesFreetext` is what Mariana actually trusts.
 *  - `bonusesJson` exists in the schema but the in-app tool doesn't read it.
 *    It's been there since 2023, originally added by a now-departed PM. About
 *    half the deals that have bonus structures fill it in; the other half
 *    leave it empty and put the bonuses in the prose only. That mismatch
 *    is one of the case-study seams.
 *
 * bonusesJson schema (when present):
 *   [
 *     { type: "gross_threshold", label: string, threshold: number, amount: number, stacks?: boolean },
 *     { type: "sellout", label: string, amount: number },
 *     { type: "attendance_threshold", label: string, threshold: number, amount: number },
 *     { type: "tier_ratchet", label: string, tiers: [{ from, to|null, percentage }] }
 *   ]
 */
export const deals = sqliteTable("deals", {
  id: text("id").primaryKey(),
  showId: text("show_id")
    .notNull()
    .unique()
    .references(() => shows.id),

  dealType: text("deal_type", {
    enum: ["flat", "percentage_of_gross", "percentage_of_net", "vs", "door"],
  }).notNull(),
  guaranteeAmount: real("guarantee_amount"),
  percentage: real("percentage"),
  percentageBasis: text("percentage_basis", { enum: ["gross", "net"] }),
  expenseCap: real("expense_cap"),
  hospitalityCap: real("hospitality_cap"),

  bonusesJson: text("bonuses_json"),
  dealNotesFreetext: text("deal_notes_freetext"),

  // Ada — current structured extraction and flags (overwritten on each run)
  extractionJson: text("extraction_json"),
  ambiguityFlagsJson: text("ambiguity_flags_json"),

  createdAt: integer("created_at", { mode: "timestamp" }).notNull(),
});

// -------- Ada: deal notes history (append-only) --------

export const dealNotesHistory = sqliteTable("deal_notes_history", {
  id: text("id").primaryKey(),
  dealId: text("deal_id")
    .notNull()
    .references(() => deals.id),
  pastedText: text("pasted_text").notNull(),
  modeUsed: text("mode_used", { enum: ["initial", "update", "replace"] }).notNull(),
  pastedAt: integer("pasted_at", { mode: "timestamp" }).notNull(),
  extractionSnapshotJson: text("extraction_snapshot_json"),
});

// -------- Ticket sales --------

export const ticketSales = sqliteTable("ticket_sales", {
  id: text("id").primaryKey(),
  showId: text("show_id")
    .notNull()
    .references(() => shows.id),
  qty: integer("qty").notNull(),
  gross: real("gross").notNull(),
  fees: real("fees").notNull(),
  capturedAt: integer("captured_at", { mode: "timestamp" }).notNull(),
});

// -------- Comps --------

/**
 * Comp tickets given away. A real source of dispute — agents sometimes argue
 * that certain comps "should have counted toward the gross" the artist's % is
 * calculated against. Most comps don't count, but the rules vary by category
 * and sometimes by deal.
 *
 * Stored as one row per category per show (aggregated count, not per-ticket).
 */
export const comps = sqliteTable("comps", {
  id: text("id").primaryKey(),
  showId: text("show_id")
    .notNull()
    .references(() => shows.id),
  category: text("category", {
    enum: [
      "artist_gl", // artist guest list
      "label", // label/management
      "press", // journalists, photographers
      "venue_staff", // venue staff and friends
      "sponsor", // sponsor reps
      "promo", // radio giveaways, 2-for-1s
      "other",
    ],
  }).notNull(),
  count: integer("count").notNull(),
  faceValue: real("face_value").notNull(),
  // Whether these comps count toward gross box office for settlement purposes.
  // Most categories don't, but the rules are inconsistent across deals.
  countsTowardGross: integer("counts_toward_gross", { mode: "boolean" })
    .notNull()
    .default(false),
  notes: text("notes"),
});

// -------- Expenses --------

export const expenses = sqliteTable("expenses", {
  id: text("id").primaryKey(),
  showId: text("show_id")
    .notNull()
    .references(() => shows.id),
  category: text("category", {
    enum: [
      "production",
      "sound",
      "lights",
      "hospitality",
      "marketing",
      "backline",
      "security",
      "other",
    ],
  }).notNull(),
  amount: real("amount").notNull(),
  description: text("description"),
  approved: integer("approved", { mode: "boolean" }).notNull().default(true),
  absorbedByVenue: integer("absorbed_by_venue", { mode: "boolean" })
    .notNull()
    .default(false),
  enteredByUserId: text("entered_by_user_id").references(() => users.id),
  enteredAt: integer("entered_at", { mode: "timestamp" }).notNull(),
});

// -------- Settlements --------

/**
 * The post-show financial reconciliation. One per show.
 *
 * Settlement is a multi-party state machine: the venue calculates a number,
 * sends it to the artist's tour manager / agent for review, they sign or
 * dispute, revisions happen, eventually a final number is agreed and money
 * moves.
 *
 * Stage timestamps below capture each transition. `status` is the current
 * stage. Most past shows are `paid`; recent ones are still in-flight.
 *
 * recoupsJson schema (when present):
 *   [
 *     { id, category: "marketing"|"hospitality_overage"|"production_overage"|"prior_advance"|"damages"|"other",
 *       label: string, amount: number, status: "agreed"|"disputed"|"withdrawn" }
 *   ]
 *
 * Recoups are venue costs that come "off the top" before artist payment.
 * They differ from regular expenses in two ways:
 *   1. They're disputed more often — the deal email language about recoups
 *      is frequently ambiguous (see the Coastal Spell dispute).
 *   2. They have their own lifecycle independent of the rest of the
 *      settlement — a recoup can be disputed even after the rest of the
 *      math is signed.
 */
export const settlements = sqliteTable("settlements", {
  id: text("id").primaryKey(),
  showId: text("show_id")
    .notNull()
    .unique()
    .references(() => shows.id),

  status: text("status", {
    enum: [
      "draft", // booker is still doing math
      "submitted", // sent to artist team
      "in_review", // artist team has opened it
      "signed", // both parties agree
      "disputed", // line items contested
      "revised", // venue sent a revision after dispute
      "finalized", // signed after revision
      "paid", // money has moved
      "voided", // show cancelled or settlement scrapped
    ],
  })
    .notNull()
    .default("draft"),

  // Stage timestamps
  draftedAt: integer("drafted_at", { mode: "timestamp" }),
  submittedAt: integer("submitted_at", { mode: "timestamp" }),
  reviewStartedAt: integer("review_started_at", { mode: "timestamp" }),
  signedAt: integer("signed_at", { mode: "timestamp" }),
  disputedAt: integer("disputed_at", { mode: "timestamp" }),
  revisedAt: integer("revised_at", { mode: "timestamp" }),
  finalizedAt: integer("finalized_at", { mode: "timestamp" }),
  paidAt: integer("paid_at", { mode: "timestamp" }),

  completedAt: integer("completed_at", { mode: "timestamp" }),
  completedByUserId: text("completed_by_user_id").references(() => users.id),

  grossBoxOffice: real("gross_box_office"),
  netBoxOffice: real("net_box_office"),
  totalExpenses: real("total_expenses"),
  totalToArtist: real("total_to_artist"),

  calculationJson: text("calculation_json"),
  recoupsJson: text("recoups_json"),

  signoffText: text("signoff_text"),
  notes: text("notes"),
});

// -------- Type exports for convenience --------

export type User = typeof users.$inferSelect;
export type Venue = typeof venues.$inferSelect;
export type Agency = typeof agencies.$inferSelect;
export type Agent = typeof agents.$inferSelect;
export type Artist = typeof artists.$inferSelect;
export type Show = typeof shows.$inferSelect;
export type Deal = typeof deals.$inferSelect;
export type TicketSale = typeof ticketSales.$inferSelect;
export type Comp = typeof comps.$inferSelect;
export type Expense = typeof expenses.$inferSelect;
export type Settlement = typeof settlements.$inferSelect;
export type DealNotesHistory = typeof dealNotesHistory.$inferSelect;

// -------- Decoded JSON helpers --------

export type Bonus =
  | {
      type: "gross_threshold";
      label: string;
      threshold: number;
      amount: number;
      stacks?: boolean;
    }
  | { type: "sellout"; label: string; amount: number }
  | {
      type: "attendance_threshold";
      label: string;
      threshold: number;
      amount: number;
    }
  | {
      type: "tier_ratchet";
      label: string;
      tiers: { from: number; to: number | null; percentage: number }[];
    };

export type Recoup = {
  id: string;
  category:
    | "marketing"
    | "hospitality_overage"
    | "production_overage"
    | "prior_advance"
    | "damages"
    | "other";
  label: string;
  amount: number;
  status: "agreed" | "disputed" | "withdrawn";
};

export type SettlementStage = Settlement["status"];

